INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B19-20261012','document_observation','B19-20261012-OBS0001','OF-US04','B07','known','{"summary_ja":"Smartlinx Goの公式FAQは、iOS・Androidストアからアプリを取得し、自分の認証情報でログインして利用を始める手順を案内する。"}','limited','unknown','documented','source_statement','{"record_category":"document_observation","research_batch":"B19-20261012","scope":"プラン・地域・版の留保は本文・limitations参照"}','アプリの利用開始手順に限る。公開ダウンロードだけでSchedulingの法人アカウントや全機能が提供されるとは記載されていない。認証情報の発行条件、対象版・モジュール、追加契約・料金は未確認。既存の一般的な勤務閲覧・応募・交代は再登録しない。',NULL,NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B19-20261012','document_observation','B19-20261012-OBS0002','OF-US04','B07','known','{"summary_ja":"Google PlayのSmartlinx開発者説明は、職員のスマートフォン打刻を、権限が認められた場合に利用できる機能として記載する。"}','limited','unknown','documented','source_statement','{"record_category":"document_observation","research_batch":"B19-20261012","scope":"プラン・地域・版の留保は本文・limitations参照"}','Androidアプリ説明の打刻権限留保。勤務閲覧・空き勤務応募まで同じ許可条件が必要とは断定しない。打刻の契約内包、法人Schedulingのエディション・モジュール境界、権限設定の実動作、課金対象者の定義は未確認。',NULL,NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B19-20261012','document_observation','B19-20261012-OBS0003','OF-US04','P01','not_found',NULL,'unknown','unknown','documented','source_statement','{"record_category":"document_observation","research_batch":"B19-20261012","scope":"プラン・地域・版の留保は本文・limitations参照"}','法人Scheduling料金への適用は記載未確認。アプリ取得の無料表示から法人サービスの0円料金明細を作らず、既存の非公開という料金概要を維持。Webサイト無料条項のB14観測とは別のストア表示を補足。','米国App StoreはSmartLinx GoをFreeと表示するが、これはストアのアプリ取得表示であり、法人向けSmartlinx Schedulingの無料プラン・基本料・利用料金を確定する資料ではない。',NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B19-20261012','document_observation','B19-20261012-OBS0004','OF-US04','O04','known','{"summary_ja":"Customer Success Teamは利用状況をもとに普及支援を行い、専門担当者が勤務・予算・コンプライアンス等の業務データを定期レビューすると説明する。"}','limited','unknown','documented','source_statement','{"record_category":"document_observation","research_batch":"B19-20261012","scope":"プラン・地域・版の留保は本文・limitations参照"}','Smartlinx全体の運用改善サービスの説明。Scheduling契約への内包・支援料金・レビュー頻度、障害窓口の曜日時間帯・言語・応答保証は未確認。定期レビューを技術SLAや独立性能検証と解釈しない。B14の研修・電話・Help Deskは再登録しない。',NULL,NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B19-20261012','document_observation','B19-20261012-OBS0005','OF-US04','P03','not_found',NULL,'unknown','unknown','documented','source_statement','{"record_category":"document_observation","research_batch":"B19-20261012","scope":"プラン・地域・版の留保は本文・limitations参照"}','継続支援の表現は課金周期・年契約の証拠ではない。非対応とも、最低契約なしとも判断しない。法人の見積・製品契約が必要。定期業務レビューの頻度を請求周期へ流用しない。','Optimizationは継続的な支援をyear after yearと説明するが、Schedulingの月払・年払、前払、最低契約期間・最低請求額の条項はこの本文で確認できない。',NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B20-20261012','document_observation','B20-20261012-OBS0001','OF-US05','B07','known','{"summary_ja":"Healthcare比較表を展開すると、SSOと公開API/SFTP連携の行にはDigital Schedulingと+Auto Schedulingの両列でチェック記号が表示される。"}','limited','unknown','documented','source_statement','{"record_category":"document_observation","research_batch":"B20-20261012","scope":"プラン・地域・版の留保は本文・limitations参照"}','公開表の表示に限る。B04では本文取得で判別できなかった列対応を補完したが、個別顧客契約・実装版・API追加費・認証方式を確定するものではない。B05/B06のSSO・API仕様は重複追加しない。自動最適化の親子行には別途表示矛盾があり、B07全体は未解決のまま。',NULL,NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B20-20261012','document_observation','B20-20261012-OBS0002','OF-US05','B07','disputed',NULL,'unknown','unknown','documented','source_statement','{"record_category":"document_observation","research_batch":"B20-20261012","scope":"プラン・地域・版の留保は本文・limitations参照"}','親行と詳細行の表示不整合を記録する。誤記か機能の意味の違いかは未特定。一方の記号を正しい契約条件として選ばず、製品非対応とも判断しない。既存B01の自動割当の存在を否定せず、B07の契約境界だけを未解決として継続。','Roster optimisationの親行はDigital Scheduling列に×、+Auto Scheduling列にチェックを表示する一方、展開した1-click roster creation等の子行は両列にチェックを表示する。標準版への自動最適化の内包は表の表示だけで確定できない。',NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B20-20261012','document_observation','B20-20261012-OBS0003','OF-US05','B07','known','{"summary_ja":"Auto Schedulingの製品ページは、Digital Schedulingの機能を土台として勤務割当・最適化を加える説明を載せ、サイトの導線ではAuto SchedulingをAdd-Onsに分類する。"}','limited','unknown','documented','source_statement','{"record_category":"document_observation","research_batch":"B20-20261012","scope":"プラン・地域・版の留保は本文・limitations参照"}','一般製品の構成説明。Healthcareの個別エディション・既存契約の権利、別料金の有無・金額、基本版の機能制限を確定する契約比較ではない。Healthcare表の親子表示の食い違いをこのページだけで解消しない。自動割当の速度・効果は既存記録を保持し再登録しない。',NULL,NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B20-20261012','document_observation','B20-20261012-OBS0004','OF-US05','O04','known','{"summary_ja":"Digital Schedulingの本文は支援を標準で含むと説明し、アプリ内ライブチャットを案内する。"}','limited','unknown','documented','source_statement','{"record_category":"document_observation","research_batch":"B20-20261012","scope":"プラン・地域・版の留保は本文・limitations参照"}','一般のDigital Scheduling製品案内。Healthcareの各契約・追加機能への適用、支援レベル、受付曜日時間・言語・応答保証は未確認。あらゆる支援や初期設定・個別開発が無料とも判断しない。既存B04の専任担当者・24時間監視を再登録しない。',NULL,NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B20-20261012','document_observation','B20-20261012-OBS0005','OF-US05','O04','known','{"summary_ja":"公式Supportページは公開ヘルプセンターとライブチャットに加え、技術支援メールsupport@rotageek.comを案内する。"}','limited','unknown','documented','source_statement','{"record_category":"document_observation","research_batch":"B20-20261012","scope":"プラン・地域・版の留保は本文・limitations参照"}','窓口と連絡手段の確認。チャットはより早いとする定性的説明で、数値の応答目標・保証ではない。有人支援の曜日時間帯・タイムゾーン・日本語対応・Healthcare契約への内包は未確認。連絡・送信・製品ログインは行わない。',NULL,NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B20-20261012','document_observation','B20-20261012-OBS0006','OF-US05','O04','known','{"summary_ja":"支援チケットを作成できるのはgroup adminsとsupervisorsに限る。会社全体のチケットを見るCustomer Tickets Portalは、アクセスを付与されたgroup adminsのみでsupervisorsは対象外。P1〜P4の優先度ガイドも掲載する。"}','limited','unknown','documented','source_statement','{"record_category":"document_observation","research_batch":"B20-20261012","scope":"プラン・地域・版の留保は本文・limitations参照"}','2024-10-01表示の公開ヘルプ。一般の問い合わせメール・チャットまで同じ役割制限とは断定しない。P1〜P4は障害の優先度説明で、応答・解決時間の数値SLAではない。現在のHealthcare契約、権限付与条件、料金内包と実操作は未確認。',NULL,NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B20-20261012','document_observation','B20-20261012-OBS0007','OF-US05','P01','not_found',NULL,'unknown','unknown','documented','source_statement','{"record_category":"document_observation","research_batch":"B20-20261012","scope":"プラン・地域・版の留保は本文・limitations参照"}','費用が要件に依存することから、特定の価格方式や個別見積制を確定しない。ROI・人件費削減を製品利用料と扱わず、金額不明を0円に置換しない。従来のHealthcareページでの金額未確認とは別のFAQを補足し、料金概要・料金明細を増やさない。','Digital Schedulingの価格FAQはソフトウェア費用が顧客の要件に依存すると説明するが、具体的金額と固定・人数・施設等の課金方式はこの本文で確認できない。',NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B20-20261012','document_observation','B20-20261012-OBS0008','OF-US05','P02','not_found',NULL,'unknown','unknown','documented','source_statement','{"record_category":"document_observation","research_batch":"B20-20261012","scope":"プラン・地域・版の留保は本文・limitations参照"}','人・拠点の権限設定の説明で、料金表や課金対象の定義ではない。管理者・休職者・兼務・複数拠点の計数や最低人数・段階料金は未確定。操作上のuser数を従量課金に流用せず、法人見積・契約で継続確認する。','People PageはUser・Supervisor・Adminの権限と主拠点・追加拠点を区別するが、その役割や拠点数がSchedulingの請求単位になるとは本文で確認できない。',NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B20-20261012','document_observation','B20-20261012-OBS0009','OF-US05','P03','not_found',NULL,'unknown','unknown','documented','source_statement','{"record_category":"document_observation","research_batch":"B20-20261012","scope":"プラン・地域・版の留保は本文・limitations参照"}','2026-08-19表示の職員設定ヘルプ。職員のcontract typeや日・時間をSaaSの請求周期・契約年数・最低請求額に置換しない。サービス契約の周期・最低条件は未確認で、最低契約なしや無料とは扱わない。','公開ヘルプのContract Typesは職員グループの労働・勤務・休憩・休暇設定を扱い、法人Schedulingサービスの月払・年払・前払・最低契約期間を定める資料ではない。',NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B21-20261012','document_observation','B21-20261012-OBS0001','OF-US10','O04','known','{"summary_ja":"Platformの支援案内は、Sparkに開始ガイド・API文書、Flowに標準導入支援・支援ポータル、Horizonに専用Slack・最適化助言担当・24/7支援を掲載し、上位プランは下位を含むと説明する。"}','limited','unknown','documented','source_statement','{"record_category":"document_observation","research_batch":"B21-20261012","scope":"プラン・地域・版の留保は本文・limitations参照"}','Employee Shift Scheduling APIを含むPlatformの案内。24/7はHorizonの説明で全プランへ拡張しない。言語、応答・解決時間、緊急連絡の手順・対象障害、各契約のSLA・費用内包は未確認。Solver Communityの無料・支援なしを商用APIへ流用しない。公開・更新日未表示。',NULL,NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B21-20261012','document_observation','B21-20261012-OBS0002','OF-US10','O04','known','{"summary_ja":"一般規約は技術支援を商用独自ソフトウェアの契約顧客向けとし、info@timefold.aiを案内する。第5.1条は別途SLAを合意しない限りサービス水準の確約を付けず、試用中には保守・支援義務がないと記載する。"}','limited','unknown','documented','source_statement','{"record_category":"document_observation","research_batch":"B21-20261012","scope":"プラン・地域・版の留保は本文・limitations参照"}','2026-04-21更新の一般条件。Orderや別SLAが優先し、契約製品・Platform/モデルの範囲はOrderで決まる。価格案内のHorizon 24/7は数値SLAを自動確定するものではなく、一方の記述を消さず条件差として保持。試用に営業支援を一切提供しないという断定はしない。',NULL,NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B21-20261012','document_observation','B21-20261012-OBS0003','OF-US10','O04','known','{"summary_ja":"Platform専用のContacting supportは支援メールsupport@timefold.aiを公開し、質問・問題への返信を案内する。"}','limited','unknown','documented','source_statement','{"record_category":"document_observation","research_batch":"B21-20261012","scope":"プラン・地域・版の留保は本文・limitations参照"}','専用支援窓口を確認したが、本文に受付時間帯・応答期限・保証・対応言語は確認できない。一般規約のinfo@timefold.aiを誤記と扱わず、一般とPlatformの導線を併存させる。連絡、アカウント・チケット作成は未実施。公開・更新日未表示。',NULL,NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B21-20261012','document_observation','B21-20261012-OBS0004','OF-US10','P02','known','{"summary_ja":"第2.2条は利用・購読モデルをOrderで定め、独自ソフトウェアで用いる一意のplanning valuesであるResources数に連動し得るとする。実使用指標はTimefoldの監視・報告で決まり、Authorized Userの定義とは別に記載する。"}','limited','unknown','documented','source_statement','{"record_category":"document_observation","research_batch":"B21-20261012","scope":"プラン・地域・版の留保は本文・limitations参照"}','Resources連動は契約で選ばれ得る方式で、全APIの固定課金方式ではない。Employee Shift SchedulingでResourcesが職員ID・シフト・期間等の何を指し、重複・休職・管理者・複数データセットをどう数えるか、最低量・段階料金・単価は未確認。Authorized UserやUIのseat数を課金Resource数に置換しない。2026-04-21更新、Order優先。',NULL,NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B21-20261012','document_observation','B21-20261012-OBS0005','OF-US10','P02','not_found',NULL,'unknown','unknown','documented','source_statement','{"record_category":"document_observation","research_batch":"B21-20261012","scope":"プラン・地域・版の留保は本文・limitations参照"}','契約・調達用の能力資料と価格表を区別。価格ページのMemory表示よりper threadという粒度が明示されるが、直ちに矛盾や追加課金を意味するとは判定しない。能力上限、計算時間、要求数、職員数、Resourcesのどれを請求に使うかはOrder未取得で未確定。通貨・単価・公開更新日もこの資料では未確認。','プラン能力表はSparkの1席、各プランのスレッド・メモリー/スレッド・テナント上限を示す参照資料で、これらの能力値をAPIの請求単位や単価としては確認できない。',NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B21-20261012','document_observation','B21-20261012-OBS0006','OF-US10','P03','known','{"summary_ja":"第13.1条はOrderに定める期間と同じ期間の自動更新を規定し、期間の記載がなければ年契約を既定とする。更新停止には現期間末の90暦日前までの通知を求める。"}','limited','unknown','documented','source_statement','{"record_category":"document_observation","research_batch":"B21-20261012","scope":"プラン・地域・版の留保は本文・limitations参照"}','Orderに期間がない場合だけの既定年契約で、Spark・Flow・Horizonの全契約を一律12か月最低契約としない。特定APIプランの月払・年払、試用後の契約、最低利用期間・最低人数・最低請求額は未確認。契約期間と請求周期を区別。2026-04-21更新。',NULL,NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B21-20261012','document_observation','B21-20261012-OBS0007','OF-US10','P03','known','{"summary_ja":"第8.1〜8.2条はOrderの請求条件を優先し、別条件がなければライセンス料を期間開始時または前、サービス料を提供後に請求し、請求日から30暦日以内の支払とする。請求通貨はEURまたはOrder記載の通貨、料金は税を含まない。"}','limited','unknown','documented','source_statement','{"record_category":"document_observation","research_batch":"B21-20261012","scope":"プラン・地域・版の留保は本文・limitations参照"}','一般規約の既定条件。支払期限30日を月払周期とは扱わず、通貨EURを全顧客の見積通貨としない。サービス料金とライセンス・API料金を区別。金額・契約別の請求周期と前払額・最低請求額は未確認で、料金明細を新規作成しない。2026-04-21更新、Order優先。',NULL,NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B21-20261012','document_observation','B21-20261012-OBS0008','OF-US10','P03','not_found',NULL,'unknown','unknown','documented','source_statement','{"record_category":"document_observation","research_batch":"B21-20261012","scope":"プラン・地域・版の留保は本文・limitations参照"}','使用量照合・追加調整と通常の請求周期を区別。Orderに従う第8条との適用関係を残し、全契約が月払・年払・四半期払のいずれかとは選ばない。Employee Shift Schedulingの具体的使用計数・請求周期・最低条件は未確定。2026-04-21更新。','第14条は四半期使用量・支払記録の監査と不足料金の次の四半期支払での調整を記載するが、これだけで全てのAPI料金を四半期請求と確定できない。',NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B22-20261012','document_observation','B22-20261012-OBS0001','OF-US21','P02','known','{"summary_ja":"年契約は実有効職員数だけでなく、契約時に選択した席数に年プラン単価と12か月を掛けて請求する。実職員数が減っても選択した契約席数が課金基準になる。"}','limited','unknown','documented','source_statement','{"record_category":"document_observation","research_batch":"B22-20261012","scope":"プラン・地域・版の留保は本文・limitations参照"}','既存の最低10席・単価・年一括払を重複登録せず、選択席数の計数を補足。年額を月次支払と扱わない。Core/Full Suite/HRの公開年プラン範囲。Flexへ一律適用しない。2026-09-07更新。',NULL,NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B22-20261012','document_observation','B22-20261012-OBS0002','OF-US21','P02','known','{"summary_ja":"My Accountant経由で追加した会計士・記帳担当・助言者1名は、職員とは別の無料閲覧用アクセスで請求職員数に含まれない。シフト配置や休暇申請はできない。"}','limited','unknown','documented','source_statement','{"record_category":"document_observation","research_batch":"B22-20261012","scope":"プラン・地域・版の留保は本文・limitations参照"}','一般のAdmin・Manager・ownerの職員プロフィールは既存根拠どおり課金対象。無料管理者席を一般化しない。1名限定の閲覧権限で、複数顧客用Advisor Centreとも別。2026-09-30更新。',NULL,NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B22-20261012','document_observation','B22-20261012-OBS0003','OF-US21','P06','known','{"summary_ja":"年契約の席数を設定画面で購入して増やすと確認時に即時請求される。先に席を購入せず職員を有効化して超過した場合は5日後に精算する。減席は次回請求日から適用され、現在の席数はそれまで残る。"}','limited','unknown','documented','source_statement','{"record_category":"document_observation","research_batch":"B22-20261012","scope":"プラン・地域・版の留保は本文・limitations参照"}','最低10席と有効職員数を下回れない条件を保持。退職者を先にアーカイブし同じ席を後任が使う場合は同時有効数が超過しない限り追加席不要。5日猶予を手動購入に適用しない。Flex・Xero経由の契約へ拡張しない。2026-09-16更新。',NULL,NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B22-20261012','document_observation','B22-20261012-OBS0004','OF-US21','P06','known','{"summary_ja":"年Coreの12席を2026年6月19日に14席へ増やす公式例は、旧12席の残期間の未使用分を控除し、新14席の同期間料金を加算する。差額は追加2席の残期間分で、期間の席単価・日数・残日数・増席数による日割りとして説明する。"}','limited','unknown','documented','source_statement','{"record_category":"document_observation","research_batch":"B22-20261012","scope":"プラン・地域・版の留保は本文・limitations参照"}','控除行を既存12席の二重請求と扱わず、例示日付を料金改定日としない。開始・終了日、総日数、丸め、税、実請求額は例示されず計算しない。原文の月換算単価と期間単価を区別し、6ドルをそのまま年日数で割らない。2026-06-24更新。',NULL,NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B22-20261012','document_observation','B22-20261012-OBS0005','OF-US21','P07','known','{"summary_ja":"請求の税地域設定がAustraliaの場合はGSTを加算し、他の国の設定ではAustralian GSTを加算しないと公式ヘルプは説明する。設定変更は次の請求から適用され、既に発行済みの請求書を自動再発行しない。"}','limited','unknown','documented','source_statement','{"record_category":"document_observation","research_batch":"B22-20261012","scope":"プラン・地域・版の留保は本文・limitations参照"}','製品の請求挙動の案内で、各国の税法・VAT免除や顧客の納税義務を判定しない。AUD価格表は税別のまま保持。地域設定から請求通貨や為替を推定しない。職員賃金ルールとは別設定。設定変更や支援連絡は未実施。2026-09-16更新。',NULL,NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B22-20261012','document_observation','B22-20261012-OBS0006','OF-US21','P06','known','{"summary_ja":"通知ヘルプはシフト公開時のSMS選択肢に$0.05 per SMSという表示があり、SMSは既定では未選択、EmailとPushはFreeと説明する。"}','limited','unknown','documented','source_statement','{"record_category":"document_observation","research_batch":"B22-20261012","scope":"プラン・地域・版の留保は本文・limitations参照"}','公開通知ヘルプの表示だけの部分確認。$のISO通貨、税込・税別、宛先国、文字分割・送信失敗、プラン差とFlex契約への適用は本文に未特定。AUDやUSDの確定価格明細に変換しない。2026-10-07更新、独立製品試験なし。',NULL,NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B22-20261012','document_observation','B22-20261012-OBS0007','OF-US21','P06','disputed',NULL,'unknown','unknown','documented','source_statement','{"record_category":"document_observation","research_batch":"B22-20261012","scope":"プラン・地域・版の留保は本文・limitations参照"}','詳細ガイドは公開ブラウザで2026-10-01更新を確認（Web取得の日付は2026-05-22、公式一覧も10-01）。価格ページ更新日は未表示。双方を保持し、旧版と断定して排除しない。対象契約・プラン・変更種別の確認が必要。','価格FAQはプラン変更が次の請求周期開始時に適用と総括する一方、詳細変更ガイドは月プラン変更・年の上位変更と増席を即時、年の下位変更と減席を次回請求日と区分する。総括を全変更へ適用できるかは未解決。',NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B22-20261012','document_observation','B22-20261012-OBS0008','OF-US21','P02','not_found',NULL,'unknown','unknown','documented','source_statement','{"record_category":"document_observation","research_batch":"B22-20261012","scope":"プラン・地域・版の留保は本文・limitations参照"}','最低方針はall plansと月3 active staffを述べるが、Flexはrostered staffで別計数かつ連絡設定のプラン。Flexへの月3人の適用または最低なしと確定しない。公式契約・Flex専用請求条件が必要。既存10.60単価は再追加しない。','Flexの最低人数・最低請求額を固有条件として確認できない。料金FAQは月内に1回以上配置した職員とSMS利用量を説明するが、最低人数を明示していない。',NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B22-20261012','document_observation','B22-20261012-OBS0009','OF-US21','P07','not_found',NULL,'unknown','unknown','documented','source_statement','{"record_category":"document_observation","research_batch":"B22-20261012","scope":"プラン・地域・版の留保は本文・limitations参照"}','単価の表示がないという旧未確認を部分的に進めたが、Flex契約SMS単価全条件の完了には不足。無料・含む・AUD税別と見なさず、追加価格明細は0件。Flex専用の現行条件または見積明細が必要。','SMSの0.05表示は見つかったが、Flexに適用する確定通貨・税処理・課金数量と宛先別単価までは確認できない。',NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B23-20261012','document_observation','B23-20261012-OBS0001','OF-US12','O04','known','{"summary_ja":"全社Serviceページは誰でも電話877-301-4786で月〜金7〜19時CTに連絡できるとし、HealthStream管理者にはCustomer Support Portalを案内する。Success Managerの支援は契約に応じた段階別と記載する。"}','limited','managed_service','documented','source_statement','{"record_category":"document_observation","research_batch":"B23-20261012","scope":"プラン・地域・版の留保は本文・limitations参照"}','ShiftWizard製品ページの800-521-0574・CSTと、一般問い合わせ/管理者ポータルを分ける。全社の時間・無料教材をShiftWizardの個別SLA・全顧客無料支援へ拡張しない。Academyの24/7は教材参照で有人緊急支援ではない。公開・更新日未表示。',NULL,NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B23-20261012','document_observation','B23-20261012-OBS0002','OF-US12','O04','known','{"summary_ja":"顧客支援ページは電話時に製品を選択し、ポータルアクセスの申請後2営業日以内に歓迎メール・アクセス情報・手順を受け取ると説明する。ポータルでは支援ケースを提出・閲覧・管理できる。"}','limited','managed_service','documented','source_statement','{"record_category":"document_observation","research_batch":"B23-20261012","scope":"プラン・地域・版の留保は本文・limitations参照"}','2営業日はポータル案内の受領説明で障害の応答・解決保証ではない。既存hStream/管理者の利用範囲と製品選択が必要で、全職員へ施設全件を無条件公開するとはしない。電話・アクセス申請・ケース提出未実施。公開・更新日未表示。',NULL,NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B23-20261012','document_observation','B23-20261012-OBS0003','OF-US12','O04','known','{"summary_ja":"ShiftWizardの支援FAQは2023年6月1日からケース管理基盤をZendeskからHealthStreamのSalesforceへ移すと説明する。製品内Help→Request Supportのフォームと担当支援チームは継続し、管理者には自分と施設のケースを集中管理する専用UserIDの申請を案内する。"}','limited','managed_service','documented','source_statement','{"record_category":"document_observation","research_batch":"B23-20261012","scope":"プラン・地域・版の留保は本文・limitations参照"}','2026年1月通知がリンクする過去の移行資料。移行日を現行営業時間や契約改定日とせず、現行全ユーザー権限・外部ポータルだけが唯一の受付・緊急SLAを確認したとはしない。ログイン・UserID作成・支援依頼なし。PDF原本を保存・文字目視確認。',NULL,NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B23-20261012','document_observation','B23-20261012-OBS0004','OF-US12','O04','known','{"summary_ja":"1月通知は2025年12月31日の14:30 CTからと2026年1月1日に有人支援を休止する具体的休業を掲載する。同ページの毎週火曜22:00〜翌1:00 CTはnetwork maintenanceとして別欄に記載する。"}','limited','managed_service','documented','source_statement','{"record_category":"document_observation","research_batch":"B23-20261012","scope":"プラン・地域・版の留保は本文・limitations参照"}','2025-12-31公開の限定日付で、現在の休日全一覧や祝日の定義を確定しない。ケース提出・セルフサービスが参照できる説明と有人稼働を分け、夜間の保守枠を支援窓口の営業時間・緊急対応と扱わない。CT表記を保持し日本時間・固定UTCオフセットへ変換しない。',NULL,NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B23-20261012','document_observation','B23-20261012-OBS0005','OF-US12','O04','disputed',NULL,'unknown','managed_service','documented','source_statement','{"record_category":"document_observation","research_batch":"B23-20261012","scope":"プラン・地域・版の留保は本文・limitations参照"}','電話877-301-4786の共通表示だけでは製品別支援チーム・保証・受付時間の同一性を証明しない。製品案内URL=https://www.healthstream.com/solution/scheduling/nurse-and-staff-scheduling/shiftwizard、通知URL=https://community.healthstream.com/viewdocument/shiftwizard-monthly-notification-ja-2。CT/CSTを同義・固定時差と推定せず、全社7:30までをShiftWizard最新時間として採用しない。公開・更新日未表示。','現在の顧客支援ページは平日7〜19:30 CTと記載するが、全社Serviceは7〜19 CT、1月ShiftWizard通知は7〜18 CT、ShiftWizard製品案内は7〜19 CST・別電話を掲載する。製品別窓口・契約・改定時点の差を確認できず営業時間は未解決。',NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B23-20261012','document_observation','B23-20261012-OBS0006','OF-US12','O04','not_found',NULL,'unknown','managed_service','documented','source_statement','{"record_category":"document_observation","research_batch":"B23-20261012","scope":"プラン・地域・版の留保は本文・limitations参照"}','一般Customer Service、製品内ケース受付、契約別Success Management、24/7教材と緊急対応を区別。具体的資料の不足を緊急支援なしとはしない。日本の導入先や国際電話、地域、夏時間の運用も未確認。一般ポータルFAQリンクはhStreamログイン画面へ移り本文未取得、ログインや別経路の回避なし。','確認した公開案内から、ShiftWizardの契約別・地域別の現行確定時間、時間外の緊急障害受付、初動・解決SLA、全休日例外と対応言語までは特定できない。',NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B24-20261012','document_observation','B24-20261012-OBS0001','OF-JP17','C02','known','{"summary_ja":"月間AI自動作成のQ&Aは、夜勤後に明けを経て休日を置きたいという質問に対し、夜勤明け後に休日を必ず入れる設定が可能と回答する。希望条件は打合せで確認し、標準設定で実現できない場合はバージョンアップや有償カスタマイズも案内する。"}','limited','addon','documented','source_statement','{"record_category":"document_observation","research_batch":"B24-20261012","scope":"プラン・地域・版の留保は本文・limitations参照"}','Full向け追加オプションという既存範囲を保持。日跨ぎ勤務の開始終了時刻、日付帰属、明けの勤務日数計数、連続夜勤、時間外の扱いは本文に未特定。すべての夜勤条件が標準・無料・必ず適用とはしない。公開・更新日未表示。実製品・境界条件の試験なし。',NULL,NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B24-20261012','document_observation','B24-20261012-OBS0002','OF-JP17','K03','known','{"summary_ja":"自動作成の手順は、職員ごとの条件を大きな変更がなければ初回に設定し、必要出勤人数を毎月の曜日別または日別に設定して実行した後、修正があれば手動で最終調整すると説明する。具体的設定内容は別途案内とされる。"}','limited','addon','documented','source_statement','{"record_category":"document_observation","research_batch":"B24-20261012","scope":"プラン・地域・版の留保は本文・limitations参照"}','初回・月次・最終調整の工程を部分確認。入力・ルール設定・マスター更新を顧客と提供者のどちらが行うか、権限・工数・代行料金は未確定。既存FAQの一般導入支援とは別の具体的な運用手順。手動調整を自動検算・自動承認と扱わない。',NULL,NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B24-20261012','document_observation','B24-20261012-OBS0003','OF-JP17','B06','known','{"summary_ja":"シフト表は店舗単位で管理し、他店のシフト状況をリアルタイムに確認でき、エリア全体の表示モードもあると説明する。機能一覧では店舗管理をFullの標準機能に分類する。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B24-20261012","scope":"プラン・地域・版の留保は本文・limitations参照"}','参照先=https://www.shifteeapp.jp/function/。表示・管理の共有についての根拠。店舗横断で必要人数・職員移動・希望を一つのモデルとして同時最適化する説明は未確認。Lightに含むとせず、Fullの店舗管理と別料金の月間AI自動作成を区別する。権限分離・更新遅延・拠点上限の実測なし。',NULL,NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B24-20261012','document_observation','B24-20261012-OBS0004','OF-JP17','E01','known','{"summary_ja":"希望提出画面は個人ごとに表示する勤務パターンを絞り込め、自由入力の表示可否と曜日ごとの固定勤務パターンを設定できる。企業ごとに希望収集を月または半月とし、提出後の再提出を許可するかも切り替えられる。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B24-20261012","scope":"プラン・地域・版の留保は本文・limitations参照"}','Light・Fullの希望収集の具体的設定を部分確認。希望提出・曜日パターンを、承認済み有給休暇の確定・取消権限・再最適化時の必須固定と同一扱いしない。希望と確定休暇を分けるデータ構造・承認状態・競合処理は未確認。既存スマホ提出・未提出通知の一般説明は重複追加しない。',NULL,NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B24-20261012','document_observation','B24-20261012-OBS0005','OF-JP17','Q04','known','{"summary_ja":"JR四国ステーション開発の掲載事例は、社員・パート等400人あまり、ショッピングセンター3店舗と直営15店舗等の運営を背景に、勤務表の収集・転記・作成・配布が通常業務の合間で3〜5日かかっていたものを、導入後は1日あれば完成できると利用者が述べる。"}','limited','unknown','documented','source_statement','{"record_category":"document_observation","research_batch":"B24-20261012","scope":"プラン・地域・版の留保は本文・limitations参照"}','提供者サイト掲載の利用者発言。400人は会社の従業員規模で、実導入の登録人数・対象店舗数・一回の計算人数ではない。日数は経過期間を含む説明で労働時間ではなく、削減率やROIを計算しない。計測期間・担当者数・入力規模・契約プラン・AIオプション使用・費用は未表示。独立評価・看護勤務の一般効果へ拡張しない。',NULL,NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B24-20261012','document_observation','B24-20261012-OBS0006','OF-JP17','Q04','known','{"summary_ja":"古河赤十字病院の掲載事例は医師の日当直の作成を導入用途とし、希望の取りまとめと調整の時間短縮、医師へのメール配布と急な変更への利用を述べる。医師希望休を考慮する自動作成がニーズとして示される。"}','limited','unknown','documented','source_statement','{"record_category":"document_observation","research_batch":"B24-20261012","scope":"プラン・地域・版の留保は本文・limitations参照"}','提供者掲載の利用者発言で、看護師・病棟の交代勤務、様式9、配置基準の適合を示すものではない。医師数・勤務枠数・期間・削減時間・希望実現の分母・プラン・費用は未表示。医師同士の変更を自動承認や変更履歴の検証とは扱わない。',NULL,NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B25-20261012','document_observation','B25-20261012-OBS0001','OF-US10','C02','known','{"summary_ja":"期間・rolling windowのルールは、既定のSTART_ONLYでは勤務開始が対象期間内のシフトを数え、前日に始まって翌朝終わる夜勤を翌日の制限に含めないと説明する。periodShiftOverlapKindをSTART_AND_ENDへ変えると、対象期間に重なる夜勤の部分もルールの集計へ含める。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B25-20261012","scope":"Employee Shift Scheduling API documentation 1.35.x; sample outputs are vendor examples; live execution and deployment applicability untested"}','1.35.xの期間ルールの集計挙動。職員の明け勤務という別コード・勤務日数の二重計数・給与上の日付帰属を確定しない。分数と日数の集計を一律に同じ計数へ読み替えず、設定対象のルールを特定する必要がある。DST・月境界・最小単位・丸めの製品試験なし。',NULL,NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B25-20261012','document_observation','B25-20261012-OBS0002','OF-US10','C02','known','{"summary_ja":"minutesWorkedLimit.countOnlyBetweenは日内の指定時間帯と勤務が重なる分だけを数える。開始時刻を含み終了時刻を含まず、終了が開始より前なら22:00〜06:00のように翌日へ跨ぐ。職員のタイムゾーンで解釈し、複数日に跨ぐ勤務は各日で重なりを計算する。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B25-20261012","scope":"Employee Shift Scheduling API documentation 1.35.x; sample outputs are vendor examples; live execution and deployment applicability untested"}','1.35.xの特定時間帯の勤務分数制限。夜勤という名称だけで法令の深夜時間を自動設定するとはしない。periodShiftOverlapKindとの組合せ、DSTの重複/欠落時刻、時差変更、丸め、明け後休日の自動生成は未検証。日本の行政・給与算式の適合を示すものではない。',NULL,NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B25-20261012','document_observation','B25-20261012-OBS0003','OF-US10','C05','known','{"summary_ja":"minutesBetweenShiftsRulesは前勤務の終了から後勤務の開始までの分数に最小・最大を設定し、REQUIREDではhard、PREFERREDではsoft制約にする。既定はREQUIRED。scope.durationは前終了＋期間を超えて始まる後勤務との組を除外し、前後の勤務タグでも対象を限定できる。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B25-20261012","scope":"Employee Shift Scheduling API documentation 1.35.x; sample outputs are vendor examples; live execution and deployment applicability untested"}','1.35.xのAPI契約モデル内のルールで商用ライセンス契約ではない。例の720分・1440分は法定値や製品固定値ではない。08:00終了と720分の例は20:00以降を許すと説明するが、scopeちょうどの境界、秒精度・重複勤務・計画窓外の前後勤務・pinned例外は独立未検証。タグinclude/excludeの同じ側での併用不可とALL既定を保持。',NULL,NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B25-20261012','document_observation','B25-20261012-OBS0004','OF-US10','C05','known','{"summary_ja":"1.35.xのabsenceModeはABSENCE_UNAWAREが既定で勤務間の経過時間を比較する。previewのABSENCE_AWAREはavailableTimeSpansまたはunavailableTimeSpansから不可用分を除き、最小休息の充足にも最大間隔の超過にもその分を数えないと説明する。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B25-20261012","scope":"Employee Shift Scheduling API documentation 1.35.x; sample outputs are vendor examples; live execution and deployment applicability untested"}','previewは変更対象で安定版の普遍仕様・全顧客で利用可能とはしない。1.35.xは文字列だがlatest対照はtypeを含むオブジェクトとspan.tagsフィルタで、入力形式を混ぜない。対照URL=https://docs.timefold.ai/employee-shift-scheduling/latest/employee-resource-constraints/shift-rotations-and-patterns/minutes-between-shifts。現行実行モデル、移行・既存入力互換、除外時のscope計算と境界実動作は未確認。休暇を休息時間から除くことが日本法で必要と判断しない。',NULL,NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B25-20261012','document_observation','B25-20261012-OBS0005','OF-US10','E01','known','{"summary_ja":"availableTimeSpansは列挙した期間だけ利用可能、unavailableTimeSpansは列挙した期間だけ利用不可とし、同一職員で両方は使えない。期間は日跨ぎで指定でき終了端はexclusive。不可用との重なりや利用可能期間で覆われない勤務分にはhard制約を適用し、例は必須シフトを未割当にして不可用を守る。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B25-20261012","scope":"Employee Shift Scheduling API documentation 1.35.x; sample outputs are vendor examples; live execution and deployment applicability untested"}','1.35.xの可用入力とhard制約。確定済み休暇を不可用へ変換する方法は実装側で設計する必要があり、申請・承認・取消・権限・休暇種類の完成済みワークフローがあるとはしない。明示不可用を単なるsoft希望へ変換しない。既定は不可用指定がなければ勤務可能。タグフィルタの適用漏れと境界の実試験なし。',NULL,NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B25-20261012','document_observation','B25-20261012-OBS0006','OF-US10','E01','known','{"summary_ja":"preferredTimeSpansとunpreferredTimeSpansはsoftの勤務希望で、働きたくない期間でも必要なら割当され得る。勤務と希望期間が重なる分数に、期間の重みと職員priority multiplierを掛けて報酬または罰点を付ける。期間の重みは省略時1、指定時は1以上の整数として説明する。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B25-20261012","scope":"Employee Shift Scheduling API documentation 1.35.x; sample outputs are vendor examples; live execution and deployment applicability untested"}','1.35.xの希望入力。希望休と確定不可用・有給休暇の承認状態を同一にしない。priorityや重みの大小から希望の全実現・公平性・法令遵守を保証しない。役割・技能・他制約と競合する。希望の収集UI・権限・取消履歴・分母を用いた実現率の独立試験なし。',NULL,NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B25-20261012','document_observation','B25-20261012-OBS0007','OF-US10','F01','known','{"summary_ja":"制約をhard・medium・softに分け、hard違反はinfeasible、mediumは必須シフトをできるだけ割り当て、softは業務目標を改善すると説明する。hard違反0の解はsoftが低くてもhard違反のある解より良い。スコア値は違反の件数そのものではなく、重み×match scoreで評価する。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B25-20261012","scope":"Employee Shift Scheduling API documentation 1.35.x; sample outputs are vendor examples; live execution and deployment applicability untested"}','1.35.xのスコア定義。mandatoryというラベルだけで全シフト充足をhardと判断しない。未割当を含むfeasibleと需要充足・最適性・解なし証明は別。0hardだけで日本の法令・未入力条件を満たすとは保証しない。既存B03の自己割当と変更抑制の一般相反は重複追加せず、今回の三段階定義を補足。',NULL,NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B25-20261012','document_observation','B25-20261012-OBS0008','OF-US10','F01','known','{"summary_ja":"休暇前後のavoidShiftCloseToDayOffRequestRulesは前日の避けるタグと翌日の避けるタグを別々に設定する。PROHIBITEDはhardで違反する割当を避け、UNPREFERREDはsoftで罰点を付けつつ割当され得る。省略時はPROHIBITED、タグのALL/ANYは省略時ALLで、片側のタグがなければその側に効果はない。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B25-20261012","scope":"Employee Shift Scheduling API documentation 1.35.x; sample outputs are vendor examples; live execution and deployment applicability untested"}','1.35.xの休暇周辺勤務ルール。休暇自体は職員のavailabilityで定義する説明。夜勤明けの休日を自動作成する完成済み日本向けパターンとはしない。0:00境界へ跨ぐ勤務、部分休・連続休、前後の暦日と職員timezoneの関係、タグ設定漏れ、例外承認は未検証。独立API試験なし。',NULL,NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B26-20261012','document_observation','B26-20261012-OBS0001','OF-JP18','E01','known','{"summary_ja":"スタッフの勤務希望を管理画面へ転記し、管理者が編集・確定した後、スタッフが勤務を変更・削除できないようロックできると機能紹介は説明する。料金ページのスタンダードにも提出・管理・確定が掲載され、無料プランへの導線がある。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B26-20261012","scope":"oplus国内向け公式公開案内。通常表示と非表示DOMを区別。プランと操作主体はlimitations参照。実動作・個別顧客契約は未検証。"}','勤務希望と確定勤務の操作段階についての部分確認。ロック固有の設定項目・プラン差・範囲・管理者の解除権限は未特定。承認済み有給休暇の扱いと同一にせず、通常ロックが自動作成中の必須固定になるとはしない。個別カスタム・契約への適用も未確認。',NULL,NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B26-20261012','document_observation','B26-20261012-OBS0002','OF-JP18','E01','not_found',NULL,'unknown','unknown','documented','source_statement','{"record_category":"document_observation","research_batch":"B26-20261012","scope":"oplus国内向け公式公開案内。通常表示と非表示DOMを区別。プランと操作主体はlimitations参照。実動作・個別顧客契約は未検証。"}','有休欄はtextContentに存在し、innerTextと見出し/AXでは非表示。将来予定・廃止・地域差・未公開機能のどれかとは推測しない。ラベルだけで無料/Pro/Pro+勤怠に有休承認が含まれるとしない。非表示の50円/ユーザー表記は現行料金として登録しない。公式の通常表示仕様・対象版/契約と実画面が必要。','料金ページのHTMLには有給休暇管理オプションの申請・許可/棄却・申請中・残有休・承認履歴の説明が存在するが、通常公開ブラウザの表示には現れない。現行の提供状態と適用基本プランを確定できない。',NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B26-20261012','document_observation','B26-20261012-OBS0003','OF-JP18','H01','not_found',NULL,'unknown','unknown','documented','source_statement','{"record_category":"document_observation","research_batch":"B26-20261012","scope":"oplus国内向け公式公開案内。通常表示と非表示DOMを区別。プランと操作主体はlimitations参照。実動作・個別顧客契約は未検証。"}','スタッフ操作のロックとoptimizer側の固定を区別。管理者の再実行や手修正・期間外・休暇・制約矛盾でも保持する仕様は不足。未確認を非対応とせず、固定ID・対象・再計算時の例を含む公開マニュアルや実試験が必要。FAQから案内された公式YouTubeのWeb取得はthrottledで本文未取得、動画内容を確認済みとしない。','確定後のスタッフ編集・削除ロック、テンプレートや有料のリピート入力の案内は確認したが、自動作成・再割当時に指定した職員・日付・業務の割当を変更しない固定仕様は確認できない。',NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B26-20261012','document_observation','B26-20261012-OBS0004','OF-JP18','N01','known','{"summary_ja":"管理者はシフト管理の設定で全スタッフへシフト管理の閲覧権限を付けられるとFAQは説明する。別のPro/Pro+勤怠のタグ説明は、特定タグの職員だけをシフト表に表示する機能として案内する。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B26-20261012","scope":"oplus国内向け公式公開案内。通常表示と非表示DOMを区別。プランと操作主体はlimitations参照。実動作・個別顧客契約は未検証。"}','全員の閲覧許可と表示フィルタを区別し、タグをアクセス拒否の機構と扱わない。閲覧設定固有のプラン差はFAQに未表示。全員は登録スタッフの文脈で、外部・他社テナント・全拠点への公開とはしない。部署別ACL、勤務希望/給与/休暇の項目権限、既定権限や取消反映の実試験は未確認。',NULL,NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B26-20261012','document_observation','B26-20261012-OBS0005','OF-JP18','N01','known','{"summary_ja":"管理者が編集できる職員情報は名前・社員番号・時給・交通費・月最大出勤数・タグを挙げる一方、メールアドレスと電話番号は職員本人がプロフィールから変更する仕様とFAQは説明する。タグは有料プランの欄と注記する。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B26-20261012","scope":"oplus国内向け公式公開案内。通常表示と非表示DOMを区別。プランと操作主体はlimitations参照。実動作・個別顧客契約は未検証。"}','管理者と本人の操作範囲の公開案内。全管理者の同一権限・権限委譲・役割階層・他拠点の個人情報閲覧を確定しない。本人のメール変更が組織間移動・管理者への昇格や認証解除になるとはしない。プロフィール変更・退会・招待・認証操作は未実施。',NULL,NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B26-20261012','document_observation','B26-20261012-OBS0006','OF-JP18','N01','known','{"summary_ja":"セキュリティチェックシートは、提供者が顧客の格納データへ同意なしにアクセスせず、格納データを利用しないと回答する。提供者組織内では役割に応じて情報資産へのアクセス・閲覧・修正権限を分ける方針も記載する。"}','limited','managed_service','documented','source_statement','{"record_category":"document_observation","research_batch":"B26-20261012","scope":"oplus国内向け公式公開案内。通常表示と非表示DOMを区別。プランと操作主体はlimitations参照。実動作・個別顧客契約は未検証。"}','提供者の自己申告による内部方針と顧客データアクセス方針。顧客側のadmin/staff権限行列、論理/物理テナント分離・API認可・支援時アクセス監査の実証ではない。全プラン/個別契約の適用、同意取得/撤回・緊急例外・委託先の手順は未特定。既存のリージョン・認証・ログ・SLAを重複追加しない。',NULL,NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B27-20261012','document_observation','B27-20261012-OBS0001','OF-JP03','E01','known','{"summary_ja":"希望休・希望勤務はスマホとPCのブラウザから提出でき、提出状況を管理者が一覧で確認できるとFAQが説明する。入力した希望と管理者による回収確認の段階を確認した。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B27-20261012","scope":"国内介護施設向けFIKAIGOの公式公開案内。機能別プラン/版制限は未表示。個別契約・実画面・境界条件試験は未確認。"}','既存のスマホ希望提出一般に加え、ブラウザ方式と管理者の提出状況一覧を確認。提出済みが承認済み休暇・勤務不可・必須制約に変わるとは記載しない。希望区分/承認状態/自動作成時の優先度は未確認。FAQに固有プラン・版制限なし。2026-03-02表示の公開/更新区別は不明。インタビューの「スマホアプリ」との呼称差からネイティブアプリの存在・非存在を断定しない。',NULL,NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B27-20261012','document_observation','B27-20261012-OBS0002','OF-JP03','E01','known','{"summary_ja":"確定後に職員へ通知し、職員個人と同じグループの勤務表を閲覧できるとFAQが説明する。希望提出の段階と、勤務表を確定して共有する段階の区別が公開案内にある。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B27-20261012","scope":"国内介護施設向けFIKAIGOの公式公開案内。機能別プラン/版制限は未表示。個別契約・実画面・境界条件試験は未確認。"}','勤務表の確定と承認済み休暇を区別。通知だけで再最適化時の固定・編集禁止・休暇承認/却下・取消履歴を確認済みにしない。全施設・他グループへのアクセスや権限拒否は本記録の対象外。FAQに固有プラン・版制限なし。既存の自分のシフト閲覧一般やExcel出力を重複追加しない。',NULL,NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B27-20261012','document_observation','B27-20261012-OBS0003','OF-JP03','C02','not_found',NULL,'unknown','unknown','documented','source_statement','{"record_category":"document_observation","research_batch":"B27-20261012","scope":"国内介護施設向けFIKAIGOの公式公開案内。機能別プラン/版制限は未表示。個別契約・実画面・境界条件試験は未確認。"}','夜勤回数の公平性は既存E04であり重複追加しない。図中の勤務表記号や交代ルールから実際の時刻・所属日・明け判定を推測しない。FAQの夜勤検索で記事項目が表示されない範囲も照合したが、全資料が存在しない証明ではない。非対応とは判定せず、日時モデルと連続勤務/月末例を含む公開仕様または許可された試験が必要。','公式製品紹介には早番・日勤・遅番・夜勤の割当を扱う案内があるが、開始終了日時、日跨ぎの所属日、夜勤明けと休日の区分、月末境界の仕様は公開本文・設定イラストから確認できない。',NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B27-20261012','document_observation','B27-20261012-OBS0004','OF-JP03','C05','not_found',NULL,'unknown','unknown','documented','source_statement','{"record_category":"document_observation","research_batch":"B27-20261012","scope":"国内介護施設向けFIKAIGOの公式公開案内。機能別プラン/版制限は未表示。個別契約・実画面・境界条件試験は未確認。"}','勤務中の休憩、勤務パターンの交代、勤務間休息を同一にしない。図の語句は実時刻ベースのinter-shift restの証明ではない。FAQインターバル検索で記事項目が表示されない範囲も照合したが、非対応・一律無制約とは判定しない。値・適用対象・緩和/矛盾処理・設定版/プラン・夜勤後の例が必要。','公開設定イラストには休憩や交代ルールと表示されるが、終業から次の始業までを実時刻で計算する休息制約、最小時間値、日跨ぎの評価、例外設定は確認できない。',NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B27-20261012','document_observation','B27-20261012-OBS0005','OF-JP03','E01','not_found',NULL,'unknown','unknown','documented','source_statement','{"record_category":"document_observation","research_batch":"B27-20261012","scope":"国内介護施設向けFIKAIGOの公式公開案内。機能別プラン/版制限は未表示。個別契約・実画面・境界条件試験は未確認。"}','担当者による記事時点の自己申告。全施設の成功・現行の未解決障害・製品独立試験とはしない。ルールが明確という感想からhard/soft・休暇承認・固定保持を推論しない。承認済み休暇が希望として緩和されないことを示す公開状態遷移/設定/例外・衝突例が不足する。旧記事の性能や拠点数を現行上限/料金へ展開しない。','住友商事の2026-01-22インタビューは希望休ルールが明確になったという施設の声を紹介するが、実際の承認済み休暇・勤務不可・希望の状態モデルと緩和禁止仕様は公開しない。複雑な勤務パターンでは自動仮組みの調整に手間がかかったケースも述べる。',NULL,NULL,'2026-10-12','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B28-20261013','document_observation','B28-20261013-OBS0001','OF-JP03','N01','known','{"summary_ja":"法人管理者、施設管理者、シフトグループ管理者、一般職員などの役割に応じて閲覧・編集範囲を制御できると権限FAQが明記する。法人・施設・グループ・職員の役割の区別を確認した。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B28-20261013","scope":"国内介護施設向けFIKAIGOの公式公開案内/一次インタビュー。FAQの版/プラン制限は未表示。事例は各記事時点。個別契約・実画面・独立権限/性能試験は未確認。"}','役割名と閲覧/編集の制御の部分確認。対象データ別の行列、他法人/他施設の認可拒否、横断管理者の範囲、提供者運用アクセス、招待/兼務/異動/権限取消時の反映は未確認。名称だけでテナント分離・最小権限の実証としない。プラン・版の制限は未表示。一般職員の端末範囲は別FAQと適用が揃わず留保。',NULL,NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B28-20261013','document_observation','B28-20261013-OBS0002','OF-JP03','N01','not_found',NULL,'unknown','unknown','documented','source_statement','{"record_category":"document_observation","research_batch":"B28-20261013","scope":"国内介護施設向けFIKAIGOの公式公開案内/一次インタビュー。FAQの版/プラン制限は未表示。事例は各記事時点。個別契約・実画面・独立権限/性能試験は未確認。"}','両FAQは2026-03-02表示で公開/更新の区別なし。誤記・別版・例外・ネイティブアプリ必須のどれかを推測しない。希望提出と管理画面利用の操作範囲が異なる可能性は留保し、PCから提出できないという禁止や全操作可を確定しない。顧客権限行列と端末/操作の公開仕様が必要。B27の希望提出一般の根拠を再採用しない。','権限FAQは一般職員をスマホアプリのみ利用と説明する一方、希望提出FAQは職員がスマホ/PCブラウザから提出できると説明する。同じ一般職員・同じ操作への端末制限なのか、役割/操作別の説明なのかを公開情報だけでは特定できない。',NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B28-20261013','document_observation','B28-20261013-OBS0003','OF-JP03','Q04','known','{"summary_ja":"2026-01-22の住友商事インタビューはSOMPOケアの介護付きホーム約300施設への導入を紹介し、同社が顧客として要件定義に参加し介護業務知見を提供したと説明する。通常の完成品購入だけでなく共同開発に関わった導入文脈を記録する。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B28-20261013","scope":"国内介護施設向けFIKAIGOの公式公開案内/一次インタビュー。FAQの版/プラン制限は未表示。事例は各記事時点。個別契約・実画面・独立権限/性能試験は未確認。"}','記事時点の関係者自己申告。現在の施設数、全介護サービス種別への適用、同時利用上限、一般顧客の標準導入条件ではない。施設別の職員/部署数・勤務体系・利用開始日・本番/実証の内訳・有償契約は未開示。担当者の立場は提供者/協力顧客であり独立評価ではない。',NULL,NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B28-20261013','document_observation','B28-20261013-OBS0004','OF-JP03','Q04','known','{"summary_ja":"2025-12-18のTMIP公式インタビューは初期段階の製品でSOMPOケアの選定へ参加し、採用後に同社が要件定義へ関与したと説明する。100床施設の月40〜50時間のシフト作成/関連込み70〜80時間は導入前の課題把握で、約1万人は利用できる規模の体制という文脈である。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B28-20261013","scope":"国内介護施設向けFIKAIGOの公式公開案内/一次インタビュー。FAQの版/プラン制限は未表示。事例は各記事時点。個別契約・実画面・独立権限/性能試験は未確認。"}','提供者の歴史的自己申告。導入前の観察対象施設名・件数・集計方法は未表示。100床を全約300施設の共通規模とせず、月時間を導入後削減量にしない。約1万人を実利用者数/同時接続保証/全製品上限としない。受賞を性能認証・有償利用証明にしない。古い月700円/IDの発言は現行の月払い契約/税/料金明細に登録しない。',NULL,NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B28-20261013','document_observation','B28-20261013-OBS0005','OF-JP03','Q04','not_found',NULL,'unknown','unknown','documented','source_statement','{"record_category":"document_observation","research_batch":"B28-20261013","scope":"国内介護施設向けFIKAIGOの公式公開案内/一次インタビュー。FAQの版/プラン制限は未表示。事例は各記事時点。個別契約・実画面・独立権限/性能試験は未確認。"}','施設の感想や概数だけを実測条件/ROI/独立性能試験にしない。平均値・全施設成功・最新の障害状況も推測しない。契約取得・営業連絡・デモは未実施。今回初めてQ04の事例条件を照合し、不足項目を継続課題として残す。既存E01の複雑勤務調整の記録は重複追加しない。','公開一次インタビューから施設種別・概数と開発参加者は確認できるが、施設別の職員数・部署数・交代体系、導入/観察期間、本番と実証の内訳、支払条件、効果の測定手順を組み合わせた再現可能な導入条件は確認できない。',NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B29-20261013','document_observation','B29-20261013-OBS0001','OF-US10','D03','known','{"summary_ja":"技能の複数条件は既定MATCH_ALLまたはMATCH_ANYを選べる。requiredSkillsExpressionはAND/ORを組み合わせた技能ID条件で、NODEの深さは2まで。同じ勤務でrequiredSkillsと必須式を併用できず、推奨技能式にも対応する。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B29-20261013","scope":"Employee Shift Scheduling API documentation 1.35.x; commercial plan applicability and live execution unconfirmed; vendor examples are not independent tests"}','1人への割当資格の組合せ。複数職員の技能を合算したチーム最低水準、数値の熟練度閾値ではない。requiredはhard、preferredはsoftで未充足割当があり得る。深さ/併用不可を除いた無制限の任意式とはしない。独立実行・顧客版/プラン未確認。',NULL,NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B29-20261013','document_observation','B29-20261013-OBS0002','OF-US10','D03','known','{"summary_ja":"requiredPairingsは指導対象職員へ指導者IDまたは職員タグを指定でき、タグ候補は少なくとも1タグで一致する。対象職員の勤務全体を覆う指導者の割当がなければhard違反となる。指導者は対象職員なしでも勤務できる。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B29-20261013","scope":"Employee Shift Scheduling API documentation 1.35.x; commercial plan applicability and live execution unconfirmed; vendor examples are not independent tests"}','技能IDに加えて指導者同伴をモデル化できる範囲。自動の熟練度査定、1指導者あたり研修生上限、数値スキル合計、臨床手技の独立可否の認定は未確認。同時刻でも別部署なら適切とは限らず、commonTagTypeなど部署条件も必要。例は独立試験ではない。',NULL,NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B29-20261013','document_observation','B29-20261013-OBS0003','OF-US10','D03','not_found',NULL,'unknown','unknown','documented','source_statement','{"record_category":"document_observation","research_batch":"B29-20261013","scope":"Employee Shift Scheduling API documentation 1.35.x; commercial plan applicability and live execution unconfirmed; vendor examples are not independent tests"}','未確認は非対応ではない。senior等の技能IDを顧客が定義しても、製品に数値熟練度マスターやチーム合算のネイティブ機能がある証明にはしない。資格の有無D01と混同せず、別の入力仕様・処置別要件・独立試験が必要。','取得した1.35.xの技能仕様は技能IDの有無・有効期間・論理式を説明するが、数値による熟練度と閾値、チーム技能の合算や職員構成比の最低水準を直接指定する公開仕様はこの範囲で確認できない。',NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B29-20261013','document_observation','B29-20261013-OBS0004','OF-US10','B06','known','{"summary_ja":"病棟・部署はタグで表し、複数アウトレットを共有職員から配置する利用例を公式に案内する。部署固有の割当資格は技能で表す。勤務ごとの表閲覧だけではなく、同一モデル内へ部署別勤務と職員を入力する用途の記載を確認した。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B29-20261013","scope":"Employee Shift Scheduling API documentation 1.35.x; commercial plan applicability and live execution unconfirmed; vendor examples are not independent tests"}','1.35.xモデルの用途案内。独立テナント間の共同最適化、既存部署表の自動統合、部署管理者の認可・変更承認、職員/施設の上限や商用プラン適用は未確認。全施設の需要充足/最適性/運用UIの完成を保証しない。',NULL,NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B29-20261013','document_observation','B29-20261013-OBS0005','OF-US10','B06','known','{"summary_ja":"部署などのタグはtagTypesで分類でき、同じタグIDを職員・勤務・ルールで再利用する。ルールのinclude/excludeEmployeeTagsとinclude/excludeShiftTagsは対象職員や勤務を絞る。単純フィルタにはトップレベルの全タグ列挙を必須としない。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B29-20261013","scope":"Employee Shift Scheduling API documentation 1.35.x; commercial plan applicability and live execution unconfirmed; vendor examples are not independent tests"}','単一モデル内のルール対象フィルタ。タグによる勤務割当資格や閲覧/編集拒否とは別で、部署タグを付けるだけでは職員の部署外割当を禁止しない。タグ型を用いるcommonTagTypeには宣言が必要。テナント認可・行単位ACLの独立検証なし。',NULL,NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B29-20261013','document_observation','B29-20261013-OBS0006','OF-US10','B06','known','{"summary_ja":"勤務地を座標で入力し、異なる勤務地の勤務間に設定した最小分数をhardで守る。locationsWorkedMaxは期間内の勤務地数をREQUIREDならhard、PREFERREDならsoftで制限する。距離はHaversineによる直線距離と説明する。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B29-20261013","scope":"Employee Shift Scheduling API documentation 1.35.x; commercial plan applicability and live execution unconfirmed; vendor examples are not independent tests"}','同じ職員の複数施設勤務の制約。道路/交通手段/渋滞から算出する実移動時間ではなく、設定値60分や週2拠点は例で既定/法定値ではない。座標一致・同一施設内の別部署・日跨ぎ/境界・休息との重複適用は未試験。必須時は未割当があり得る。',NULL,NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B29-20261013','document_observation','B29-20261013-OBS0007','OF-US10','B06','known','{"summary_ja":"commonTagTypeは同時勤務の職員に同じ部署/場所等のタグを要求でき、groupByEmployeeTagで職員グループへ適用する。previewのgroupShiftsPerDayLimitはそのグループの同一日・共通タグの勤務時刻の種類数を上限で制限する。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B29-20261013","scope":"Employee Shift Scheduling API documentation 1.35.x; commercial plan applicability and live execution unconfirmed; vendor examples are not independent tests"}','職員グループの共同勤務条件で、組織階層や部署ごとのデータ閲覧権限ではない。groupShiftsPerDayLimitはpreviewで変更対象、商用プラン/現行実行版の適用は未確認。上限1は同じ開始終了の条件で、施設人数上限/需要配置数にしない。latestとの版差・独立実行なし。',NULL,NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B30-20261013','document_observation','B30-20261013-OBS0001','OF-US10','G04','known','{"summary_ja":"計算済み勤務表のscore-analysisは保存された制約別スコアを取得できる。includeJustifications=trueを指定すると、各制約matchに関係する勤務・職員・時間帯などの具体的オブジェクトを返す例があり、省略時の概要だけの応答と区別する。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B30-20261013","scope":"Official 1.35.x documentation; commercial plan applicability and live execution unconfirmed; vendor examples are not independent tests"}','1.35.xの出力仕様。違反箇所の根拠であり、最小の矛盾制約集合や全体の解なし証明ではない。全制約のjustification形状・一意ID/参照完全性・JSONと説明の整合・商用プラン/顧客実行版は独立未検証。B03の手作成表採点一般は再登録しない。',NULL,NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B30-20261013','document_observation','B30-20261013-OBS0002','OF-US10','G04','known','{"summary_ja":"特定職員が特定勤務へ割り当てられなかった理由は、その割当を強制した仮の勤務表を作り、POST score-analysis?includeJustifications=trueで最良発見解と比較する方法を案内する。hard違反とsoft悪化を制約・対象オブジェクトへ結び付ける。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B30-20261013","scope":"Official 1.35.x documentation; commercial plan applicability and live execution unconfirmed; vendor examples are not independent tests"}','1.35.xの反実仮想比較手順で、元の結果から全代替案を自動列挙する証明ではない。仮の割当以外の入力/設定が同じかを管理する必要がある。局所最良/最良発見解と大域最適は別。最小矛盾集合・独立検算・未入力条件を含む法令適合は未確認。',NULL,NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B30-20261013','document_observation','B30-20261013-OBS0003','OF-US10','G04','known','{"summary_ja":"PlatformのScore analysisでは、制約が入力不足や未発火で無効になった場合にeffective weightを0と表示し、設定した重みと区別する。matchedフィルタはスコアに影響した制約、triggeredフィルタは有効だが罰点0の制約も表示する。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B30-20261013","scope":"Official Platform latest mutable guide; not pinned ESS runtime documentation; commercial plan applicability and live execution unconfirmed; vendor examples are not independent tests"}','Platform latestのUI説明で固定ESS1.35.x仕様そのものではない。重み0を常に手動無効化とせず、matched一覧にないことを違反検査済みや未定義の証明にしない。API応答そのものが変更されたとの説明ではない。プラン・現行UI/実行版・独立動作未確認。',NULL,NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B30-20261013','document_observation','B30-20261013-OBS0004','OF-US10','G04','known','{"summary_ja":"recommend-employeesはincludeJustifications=trueを任意に指定でき、省略時は候補別の全体スコア差・制約差・match件数差、指定時はmatchesDiff内に勤務IDとdescription等のjustificationを含む応答例を示す。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B30-20261013","scope":"Official 1.35.x documentation; commercial plan applicability and live execution unconfirmed; vendor examples are not independent tests"}','1.35.xの候補比較出力。maxNumberOfRecommendationsで候補数を制限するため全職員の不可能理由一覧ではない。JSON例のscoreDiffを使用し、本文のscoreDiffs表記と混ぜない。導入例の可用/不可用両配列と専用仕様の併用禁止は適用未整理で、実行可能な入力例として認証しない。最小原因集合・大域最適・独立試験なし。',NULL,NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B30-20261013','document_observation','B30-20261013-OBS0005','OF-US10','G04','known','{"summary_ja":"Assignability analysisは他の勤務が空という条件で、各勤務へhard違反なく割当可能な職員の割合を入力から計算する。0%はその勤務に資格を満たす職員がいない、0%超は少なくとも1候補と説明し、阻害するhard制約と職員を確認できる。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B30-20261013","scope":"Official 1.35.x; visualization explicitly preview documentation; commercial plan applicability and live execution unconfirmed; vendor examples are not independent tests"}','可視化はpreview・早期利用は問い合わせで、一般プランへ自動適用しない。各勤務に候補がいても全勤務の同時充足は保証しない。最適化後の結果検証や最小矛盾集合ではない。Include assignedの有効/無効の説明が同じ段落で相反し、フィルタ実動作は確定しない。API詳細スキーマ/独立実行なし。',NULL,NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B30-20261013','document_observation','B30-20261013-OBS0006','OF-US10','F04','not_found',NULL,'unknown','unknown','documented','source_statement','{"record_category":"document_observation","research_batch":"B30-20261013","scope":"Official Platform latest mutable guide; customer integration examples documentation; commercial plan applicability and live execution unconfirmed; vendor examples are not independent tests"}','自然言語で理由を聞くこと、条件JSONを開発者が作ること、標準製品で自然言語からルールを生成することを分離する。対照URL=https://docs.timefold.ai/employee-shift-scheduling/1.35.x/user-guide/input-datasets/model-input。解釈プレビュー、誤解/曖昧入力の拒否、修正/承認/取消履歴、日本語、対象プラン/版、外部LLM送信/学習条件は未確認。非対応とも標準ネイティブ提供とも判断しない。','Platformガイドの会話型計画は、顧客がAI agentで職員の質問や問題提起を受ける利用例である。対照の1.35.x Model inputはcontracts/globalRules等の構造化JSONを説明するが、会話を実際の最適化ルールへ変換する標準機能・入力仕様は取得範囲で確認できない。',NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B31-20261013','document_observation','B31-20261013-OBS0001','OF-US10','N01','known','{"summary_ja":"Platformはテナントを主な分離境界とし、モデル・データセット・メンバー・APIキー等をテナントごとに保持し、他テナントのデータをDB/アプリ両層で隔離すると説明する。所属する複数テナントの切替は可能。EU/USの名前空間は別で、self-hostedは1設置1テナントと明記する。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B31-20261013","scope":"Official Platform latest; Cloud vs self-hosted conditions documentation; commercial plan applicability and live implementation unconfirmed; vendor access claims not independently tested"}','Platform latestの提供者記載で侵入/権限試験や第三者保証ではない。Cloudの複数テナントとself-hostedの単一テナントを同じ条件にしない。業務の施設/部署タグをテナント分離と見なさず、地域間データ同期・テナント数/追加費用・顧客プラン適用は未確認。',NULL,NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B31-20261013','document_observation','B31-20261013-OBS0002','OF-US10','N01','known','{"summary_ja":"Viewerはテナント内のモデル・全データセット・設定プロファイルを閲覧、Userは作成/再実行/取消や名称・タグ編集、Administratorは設定プロファイル・キー・メンバー・モデル等の管理を追加すると説明する。招待時に期限を指定し、Solutions Engineerの一時アクセスにも利用する案内がある。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B31-20261013","scope":"Official Platform latest; Experiments role exception explicitly preview documentation; commercial plan applicability and live implementation unconfirmed; vendor access claims not independently tested"}','Platform latestの役割一覧。部署/本人単位のデータ行ACL・ロール変更や期限切れの反映時間・運用者の恒常アクセス範囲・実拒否は未確認。Experimentsはpreviewで、通常のtenant role一覧とは別にModel API keyの操作scopeで制御する但し書きがある。Userという名称だけで実験操作可と一律判断しない。',NULL,NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B31-20261013','document_observation','B31-20261013-OBS0003','OF-US10','N01','known','{"summary_ja":"Model APIキーはユーザー文脈を持たずテナントと選択モデルへ紐付き、全モデル/選択モデルと全操作/選択操作を選べる。期限未指定は30日、revoke後の後続API呼出は失敗すると説明する。ReadのみではPOST recommendationsやPOST score-analysisを呼べず、作成権限の対象として表記する。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B31-20261013","scope":"Official Platform latest; Model API permissions documentation; commercial plan applicability and live implementation unconfirmed; vendor access claims not independently tested"}','Platform latestの文書条件で実拒否/期限境界/取消伝播/処理中リクエストは未試験。全管理者にキーがvisibleという記載を秘密値の再表示可否と同一にしない。権限名とHTTPメソッドは単純一致せず、DELETE /idはUpdate、/id/purgeはDelete、取得済みscore-analysisのGETは各操作列で可と表記する。プラン/実行版/外部顧客ACLは未確認。',NULL,NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B31-20261013','document_observation','B31-20261013-OBS0004','OF-US10','N01','known','{"summary_ja":"GET /api/aboutmeは現在のキー名、所属テナントとplan、resource/operationsの権限を返す診断方法を案内する。キーがない/未知/期限切れの場合は401と説明し、例のAPIキーcallerはroleやemailがnullでもMODEL/EXPERIMENTの操作権限を別に持つ。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B31-20261013","scope":"Official Platform latest; caller identity and model-scoped API documentation; commercial plan applicability and live implementation unconfirmed; vendor access claims not independently tested"}','Platform latestの応答例で今回呼び出していない。例のENTERPRISEや全CRUDを顧客の契約/既定権限にしない。キーcallerのrole=nullを無権限・匿名職員の証明にせず、endpoint応答の権限情報と実データアクセス拒否を分ける。無効化・モデルscope・トークン共有時の実動作は未検証。',NULL,NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B31-20261013','document_observation','B31-20261013-OBS0005','OF-US10','K03','known','{"summary_ja":"1.35.xの統合手順は、顧客システムが業務データを集め入力を作り、Timefoldへ送信し、返された最適化結果を顧客側で処理する流れを説明する。計画データと計画モジュールは顧客自身のbackendまたはCRM内に保持する構成とする。"}','limited','unknown','documented','source_statement','{"record_category":"document_observation","research_batch":"B31-20261013","scope":"Official Employee Shift Scheduling documentation 1.35.x documentation; commercial plan applicability and live implementation unconfirmed; vendor access claims not independently tested"}','顧客側実装を含む手順の部分確認で、完成済み職員UI・マスター作成・日本の勤務規則の自動設定/ベンダー代行を保証しない。B01のAPI分類/M04のREST一般は再登録しない。実際の担当者/代行/共同設定/個別開発、工数・データ整備・移行責任・契約プランの作業分担は未確認。',NULL,NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B31-20261013','document_observation','B31-20261013-OBS0006','OF-US10','K03','known','{"summary_ja":"Platformの設定プロファイルはモデル単位で、read-onlyのStandardを既定とし、独自プロファイルを作成/複製して重み・モデル設定・solve設定を保存する。適用はIDまたは名前/画面から選び、入力設定→一時override→profile→親dataset→model既定の順で決まると説明する。"}','limited','unknown','documented','source_statement','{"record_category":"document_observation","research_batch":"B31-20261013","scope":"Official Platform latest; configuration and tenant-plan ceilings documentation; commercial plan applicability and live implementation unconfirmed; vendor access claims not independently tested"}','Platform latestの設定手順で、固定ESS1.35.xモデルの全設定や顧客版を認定しない。Members資料はprofile作成/編集/削除をAdministratorに追加するが、dataset overrideの操作権限の全行列は未確認。入力プロファイルの選択と編集を同一にしない。model/tenant planの上限があり、名前変更で指定先が一致しなくなる留保を保持。作業代行/検収/工数/契約適用は未確認。',NULL,NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B32-20261013','document_observation','B32-20261013-OBS0001','OF-US10','K01','not_found',NULL,'unknown','unknown','documented','source_statement','{"record_category":"document_observation","research_batch":"B32-20261013","scope":"ESS documentation 1.35.x; official document/specification scope only; live customer version/plan and exit contract applicability unconfirmed"}','構造化JSONの投入は既存Excelの読取対応ではない。今回の公開手順・入力検証・OpenAPIの限定確認で、製品全体にExcel機能がないとは断定しない。顧客側変換器や別商品/個別開発の存在、書式対応、変換精度/工数、実画面・ファイル試験と適用プランは未確認。B31の一般連携主体を再登録しない。','1.35.xの導入例はemployees/shiftsを含むsample.jsonを作成し、New planのCustomからJSONをアップロードする手順を示す。今回確認した入力案内では、セル結合・独自記号・複数シートを含む既存Excel勤務表の直接取込/自動変換仕様を確認できなかった。',NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B32-20261013','document_observation','B32-20261013-OBS0002','OF-US10','M08','known','{"summary_ja":"Plans overviewは検索/フィルターに一致したデータセットをExport CSVで出力するが、対象は直近100件までと説明する。Plansは関連solveの連鎖ごとに最新revision、Revisionsは各revisionを表示する。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B32-20261013","scope":"Platform latest; mutable; official document/specification scope only; live customer version/plan and exit contract applicability unconfirmed"}','Platform latestの一覧CSVに関する上限で、希望・規則・設定・全履歴を内包した全量アーカイブを保証しない。画面のrevision表示とCSV列/全revision出力は別で、100件超の分割取得・整合性・削除済み範囲・CSV実試験・顧客プランは未確認。解約後の可用期限/費用も未確認。',NULL,NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B32-20261013','document_observation','B32-20261013-OBS0003','OF-US10','M08','known','{"summary_ja":"設定プロファイルは名称・説明・制約重み・モデル設定・solve設定を含む全体をJSONへExportし、read-onlyのStandardも対象とする。再Importは常に新規プロファイルを作り、既存へ上書き/mergeせず、元のdefault指定を自動継承しない。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B32-20261013","scope":"Platform latest; mutable; official document/specification scope only; live customer version/plan and exit contract applicability unconfirmed"}','Platform latestの個別profile移送。別モデルや一致しないparameterは汎用import error、同一モデルのminor版間移送等が推奨される。勤務表/希望/データセット履歴/権限等が同梱される保証や全profile一括出口、再現互換性、解約期限/費用・プランは未確認。B31の作成/選択/優先順位を再登録せず、既存正規化文書を再利用する。',NULL,NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B32-20261013','document_observation','B32-20261013-OBS0004','OF-US10','M08','known','{"summary_ja":"データセットのOutputでは計画の全詳細をJSONファイルとしてダウンロードできると説明する。Visualizationは出力品質のspot-check用として別に案内される。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B32-20261013","scope":"Platform latest; mutable; official document/specification scope only; live customer version/plan and exit contract applicability unconfirmed"}','Platform latestの単一計画solution outputで、全テナントの入力希望/規則/実効設定/全revision/監査を同梱する全量出口ではない。1件の計画のfull detailsを契約終了時のfull exportへ拡張しない。実ファイル・プラン・解約後の取得期限/費用は未確認。B30の採点/justification一般を再登録せず既存文書を再利用する。',NULL,NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B32-20261013','document_observation','B32-20261013-OBS0005','OF-US10','M08','known','{"summary_ja":"公開OpenAPIのGETはID単位で/inputをEmployeeSchedule、/configをModelConfiguration2、/logsをLogInfo、/model-requestを完全入力requestのJSONとして返す仕様を示す。個別datasetの入力と実効設定とsolveログを別に取得する設計が確認できる。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B32-20261013","scope":"Mutable live OpenAPI; info.version=v1; not pinned ESS1.35.x; official document/specification scope only; live customer version/plan and exit contract applicability unconfirmed"}','info.version=v1の可変公開specで固定ESS1.35.xのruntime認定ではない。仕様閲覧のみでAPI実行/認証なし。入力・実効設定・solveログ・完全requestは別artifactで、solveログをtenant監査にしない。404/401/403/429等を定義し、終了契約下の可用性/全revisionの完全列挙/解約費用期限/実取得や復元性は未確認。',NULL,NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B32-20261013','document_observation','B32-20261013-OBS0006','OF-US10','M08','not_found',NULL,'unknown','unknown','documented','source_statement','{"record_category":"document_observation","research_batch":"B32-20261013","scope":"Platform latest; mutable; official document/specification scope only; live customer version/plan and exit contract applicability unconfirmed"}','監査の画面閲覧を監査export保証にしない。限定公開文書の未確認結果で、解約出口機能の不存在や無料/無期限を断定しない。個別契約の追加権利/代行費用/期限、tenant-wide archive・全revision/削除済みデータ保持・実可搬/復元性は未確認。既存B21の非公開条件巡回や営業連絡は行わない。','監査ガイドはテナントごとに設定イベントを閲覧し、APIキー・profile・member/model・secrets等の種別とactor/IP/time等を確認する手順を示す。今回の公開入出力資料では、希望・規則・設定・全履歴/監査を機械可読で解約時に全量取得する範囲、費用、期限を確認できなかった。',NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B33-20261013','document_observation','B33-20261013-OBS0001','OF-US10','C01','known','{"summary_ja":"1.35.xはcontractsのshiftRotationRulesにWEEKLY/CUSTOMと複数rotationGroupsを定義し、勤務タグで勤務種別をまとめる。週次REQUIREDはある期間の1groupから次期間は別groupへ移るhard制約で、違反する割当は未割当になる。PREFERREDはsoft条件である。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B33-20261013","scope":"ESS fixed documentation 1.35.x; documented partial scope, not independent product validation; commercial plan and current runtime unconfirmed"}','モデル化された勤務種別の交代を部分確認したが、病棟内の二交代/三交代混在プリセット、日本の夜勤体系/境界日/祝日跨ぎ・時差/DST・複数契約競合の実試験は未確認。rotationGroupのANYやinclude/exclude排他はこのルールの条件で、既存B29のタグ一般を反復しない。固定文書版は顧客実行版/プランの認定ではない。',NULL,NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B33-20261013','document_observation','B33-20261013-OBS0002','OF-US10','C01','known','{"summary_ja":"CUSTOM REQUIREDのrequiredRotationPeriodMaxSizeInDaysは同じrotationGroupの期間の最大日数を定める。公式例は1月1/2/3/5日の朝勤務を5日間、1月8/10/11/13日の午後勤務を6日間と数え、異なるgroup期間の間の1月6/7日の休日を含めない。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B33-20261013","scope":"ESS fixed documentation 1.35.x; documented partial scope, not independent product validation; commercial plan and current runtime unconfirmed"}','最大日数は割当勤務の件数や連続勤務日数と同じではない。期間内の空き日とgroup間の休日の扱いを混同しない。夜勤跨日・ローテーション開始/終了境界・前月からの継承・複数体系混在/三交代固定順序は未検証。PREFERREDのmin/maxをREQUIREDの最低日数保証にしない。週次とCUSTOMを1観測に混ぜず、同一文書数を水増ししない。',NULL,NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B33-20261013','document_observation','B33-20261013-OBS0003','OF-US10','C01','known','{"summary_ja":"multiDayShiftSequencePatternRulesを契約に設定し、職員へ契約を紐付け、勤務タグに一致するONとOFFの順序を定義する。PREFERREDは部分的なpattern要素にsoft報酬、UNPREFERREDは完全一致した列にsoft罰則、PROHIBITEDは翌日のLate→Early等の列をhard条件で禁じる例を示す。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B33-20261013","scope":"ESS fixed documentation 1.35.x; documented partial scope, not independent product validation; commercial plan and current runtime unconfirmed"}','勤務列の表現・例を部分確認しただけで、混在交代制度・臨床配置基準・法令適合・月境界/夜勤日帰属の保証ではない。PROHIBITEDの説明はmulti dayとsingle dayの制約名を併記しており、名称の誤記/実制約対応は未確定。soft条件は満たされなくても割当され得る。実出力、顧客現行版/プランは未確認。',NULL,NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B33-20261013','document_observation','B33-20261013-OBS0004','OF-US10','I06','known','{"summary_ja":"公開ガイドは特定技能を持つ職員を追加/削除した入力を送って生産性の変化を比較し、勤務pattern・skill mix・team構成を変えるwhat-if simulationを案内する。Experimentsで変種を体系的に比較する導線も示す。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B33-20261013","scope":"Platform latest; mutable; documented partial scope, not independent product validation; commercial plan and current runtime unconfirmed"}','候補条件を利用者が用意する比較手順で、最適な採用資格/曜日/時間や最小採用必要数を自動算出/証明するとは確認できない。曜日/時間の可用条件・契約・費用・需要/期間を揃えた候補別実評価、改善量の統計確度、プラン/実行版とpreview利用権は未確認。B29技能やB30採点の一般事項は再登録しない。',NULL,NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B33-20261013','document_observation','B33-20261013-OBS0005','OF-US10','I06','known','{"summary_ja":"previewのExperimentsは既存dataset IDを参照し、新しい入力は先にsolveせず登録する。入力変種とmodel version/profile/overrideを定義するscenarioを組み合わせ、M datasets×N scenariosのsolveを行い、scenarioごとの集計指標とbaseline差分を比較する。作成はAPI、結果参照はUIと説明する。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B33-20261013","scope":"Platform latest; preview; documented partial scope, not independent product validation; commercial plan and current runtime unconfirmed"}','入力を作り分ける操作とscenarioの解き方設定を区別する。API例はscenarioごとのdatasets配列だが文章は全M×Nであり、異なる集合の実行網羅性は未試験。集計指標を個別資格/曜日/時間の不足原因や最小採用数の証明へ拡張しない。preview・早期利用問い合わせ・プラン/費用/資源配分は未確認。API/実験/キー/権限変更なし。',NULL,NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B33-20261013','document_observation','B33-20261013-OBS0006','OF-US10','I06','known','{"summary_ja":"previewのComparison UIは選択datasetの人員/仕事数等のinput metricsとoutput metrics・scoreを比較する。列は単一または複数datasetの平均で、上限10列・1列50dataset。実効configurationは単一dataset列でのみ表示し、個別職員指標/資源割当の比較は対象外と明記する。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B33-20261013","scope":"Platform latest; preview; documented partial scope, not independent product validation; commercial plan and current runtime unconfirmed"}','高水準の比較で、採用候補ごとの勤務成立/不足解消の因果や資格・曜日・時間の必要人数を直接証明しない。平均による不足ピークの隠れ・期間/需要/制約/版の差を別に評価する必要がある。previewと商用プラン/実動作は未確認。CSV/exportは本ターンの観測へ重複追加せず、M08の全量出口保証にも使わない。',NULL,NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B34-20261013','document_observation','B34-20261013-OBS0001','OF-US09','C05','known','{"summary_ja":"APIガイドはminHoursBetweenShiftsを時間単位の数値と定義する。会社方針と個人customの同じ休息ルールが重なる場合は大きい値を採用し、個人GETは有効な会社/個人ルールを返す。無効な方針は適用されない。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B34-20261013","scope":"Operations scheduling policies; API guide with v1 endpoints; schedulerApi entitlement required; documented partial scope; no independent product validation or customer runtime confirmation"}','終業→次始業の差の実計算、等号・端数丸め、夜勤跨日/月境界/DST、複数勤務表の対象勤務対は未試験。11.0はAPI例で既定/法定値ではない。helpの複数方針追加案内とAPIの会社方針1件/再割当置換は表面仕様が異なり、実整合未確認。',NULL,NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B34-20261013','document_observation','B34-20261013-OBS0002','OF-US09','C05','known','{"summary_ja":"休息ルールにもpreventClaimがあり、trueは違反するOpen Shift応募を阻止し、falseは管理者へ報告して応募を阻止しない。ガイドの既定はtrue、休息11.0時間の例はfalse。APIにはschedulerApi利用条件がある。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B34-20261013","scope":"Operations scheduling policies; documented preventClaim switch; schedulerApi plan limitation; customer entitlement unconfirmed; documented partial scope; no independent product validation or customer runtime confirmation"}','APIのenforcesという総括を全手動操作のhard拒否へ拡張しない。既存helpは草案保存/公開時に管理者へ警告と説明し、応募阻止も選択式。無条件hard制約・Expert全契約のAPI権・実API応答は未確認。設定もAPI呼出しも行っていない。',NULL,NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B34-20261013','document_observation','B34-20261013-OBS0003','OF-US09','C05','known','{"summary_ja":"2026-08-12のIssues説明は、勤務間の最低時間をScheduling Rules違反の対象に含め、その種類に必要な機能はExpertからと明記する。一般Issuesは全プランで、種類ごとの表示は設定でON/OFFにできる。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B34-20261013","scope":"Operations Expert and above for Scheduling Rules issues; generic Issues all plans; help 2026-08-12; documented partial scope; no independent product validation or customer runtime confirmation"}','違反の表示を隠す操作と休息ルールの無効化・応募阻止を同一視しない。最低休息の数値域、実警告文、無効化時のhard動作、境界テスト未確認。既存の一般ルール/警告説明を再登録せず、今回の追加事項は休息種類のプラン境界と表示切替。',NULL,NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B34-20261013','document_observation','B34-20261013-OBS0004','OF-US09','K01','known','{"summary_ja":"2025-08-25の取込手順はテンプレートの1行を1勤務として編集し、CSVへ保存してアップロードする。日付/開始終了/休憩分/Job/場所等を扱い、識別子をmappingして職員へ紐付け、確認後も草案となる。Basic Operations以上が対象。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B34-20261013","scope":"Operations Basic and above including Expert by documented inheritance; template-to-CSV; help 2025-08-25; documented partial scope; no independent product validation or customer runtime confirmation"}','ExpertはBasic/Advanced機能を含むという既存公式資料と整合するが、xlsx直接取込の証明ではない。セル結合・独自勤務記号・複数シートの元表保持、変換工数・導入時間・再取込更新/重複は未確認。テンプレート取得/製品取込試験なし。',NULL,NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B34-20261013','document_observation','B34-20261013-OBS0005','OF-US09','K01','known','{"summary_ja":"障害解説はExcel/PDF/Numbers形式を不可としてCSVを要求し、Job/Shift title両列の存在と少なくとも一方の値を必要とする。未知Jobは新規作成/既存対応/無視、Sub-job列はnote/既存field/無視を案内する。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B34-20261013","scope":"Operations Basic and above; CSV-only troubleshooting; help 2025-08-25; unresolved same-date mapping differences; documented partial scope; no independent product validation or customer runtime confirmation"}','同日付の取込記事はJob/Sub-jobを列挙し、未知parent/sub-jobは既存Jobへ対応または無視とする。新規作成可否・Sub-job専用取込に説明差があり、版/データ条件/誤記のどれかは未確定。CSVを既存Excel表直接対応へ読み替えない。',NULL,NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B34-20261013','document_observation','B34-20261013-OBS0006','OF-US09','K01','known','{"summary_ja":"日付形式の不一致や日付なしは取込当日へ、職員名不明は未割当へ、開始/終了時刻不足はアカウント既定時間へ補完されると障害解説が説明する。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B34-20261013","scope":"Operations Basic and above; documented missing-data defaults; help 2025-08-25; documented partial scope; no independent product validation or customer runtime confirmation"}','補完が既存勤務表の意図を保持する保証ではない。日付設定・職員識別・欠落値を確認する必要がある。日跨ぎ/タイムゾーン/文字コード/大量行/境界の実取込、エラー拒否と補完の詳細条件、工数は未測定。',NULL,NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B35-20261013','document_observation','B35-20261013-OBS0001','OF-US09','L01','known','{"summary_ja":"管理者がAvailabilityと希望提出を有効にした勤務表で、本人はモバイルアプリのMy availabilityから日付・希望/不可・詳細を選びConfirmする。Only meの＋からは不可だけを追加でき、希望はMy availabilityのみ。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B35-20261013","scope":"General Job Scheduler help 2026-01-28; availability enabled; Operations Expert entitlement not explicitly stated; documented partial scope; no independent product test, current customer version or contract confirmation"}','本人アプリの手順を部分確認。iOS/Android別対応・アプリ版・本人ブラウザ提出・承認/確定・追加料金/Expert契約の利用権・権限拒否の実試験は未確認。管理者の設定を本人が変更できるとしない。未記入日の可用扱いや既存の自動割当考慮は再登録しない。',NULL,NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B35-20261013','document_observation','B35-20261013-OBS0002','OF-US09','L01','known','{"summary_ja":"勤務表ごとに不可の追加/編集/削除を日・時間・分の指定期間内で止められる。期限は勤務表タイムゾーンの各日開始から測り、期間内も閲覧は可能。変更ロックはモバイルアプリとdashboard双方に適用されると説明する。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B35-20261013","scope":"General Job Scheduler help 2026-08-18; per-schedule unavailability change window; customer plan/version unconfirmed; documented partial scope; no independent product test, current customer version or contract confirmation"}','勤務開始時刻基準や全勤務表共通期限と読み替えない。prefer to workまで同じロックが及ぶか、等号/端数/DST/深夜の境界・管理者代行の例外・Expertの利用権/版は未確認。期間2日は例で既定値/法定値ではない。設定/期限試験なし。',NULL,NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B35-20261013','document_observation','B35-20261013-OBS0003','OF-US09','L01','known','{"summary_ja":"本人はアプリMy Availabilityから終日または時間帯の不可を登録できる。既に割当済みの勤務がある場合は不可を記入できず、重複の表示が出ると説明する。管理者/ownerは不可があっても勤務を配置できる。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B35-20261013","scope":"General Job Scheduler help 2026-08-18; mobile user path; admin override documented; customer plan/version unconfirmed; documented partial scope; no independent product test, current customer version or contract confirmation"}','希望提出の許否と管理者配置の許否を区別。割当済みの日全体か重複時間帯だけか、複数勤務表・草案/公開済み勤務・代行削除/変更、本人認証と権限は未試験。1月の希望ガイドはGeneral tab、8月の不可ガイドはMobile app tabで設定場所が異なり、現在UIは未確認。',NULL,NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B35-20261013','document_observation','B35-20261013-OBS0004','OF-US09','K03','known','{"summary_ja":"公式Proサービスは認定proによるSchedule設定を案内し、勤務・テンプレート・繰返し・view・availabilityを対象に挙げる。50分セッション40 USDと表示し、サービス範囲は購入済みsubscription planに従う。"}','limited','unknown','documented','source_statement','{"record_category":"document_observation","research_batch":"B35-20261013","scope":"Optional certified-pro setup; public service page; depends on subscribed plan; no confirmed customer quotation; documented partial scope; no independent product test, current customer version or contract confirmation"}','製品名Operations Expertと担当者proを混同しない。Expert標準の無料設定代行ではない。全休息/医療制度条件の設定・顧客要件定義/データ準備の分担・必要回数/工数/検収/版は未確認。単価はK03条件として記録し、時間単位の表記差があるため料金明細追加なし。予約/購入なし。',NULL,NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B35-20261013','document_observation','B35-20261013-OBS0005','OF-US09','K03','known','{"summary_ja":"FAQは、設定meeting後に必要な作業を認定partnerが単独で続け、成果を提示して調整する方法を説明する。onboarding meetingは顧客へ事業/解決策/設定例を説明し、その後は顧客が独力で継続する方法と分ける。"}','limited','unknown','documented','source_statement','{"record_category":"document_observation","research_batch":"B35-20261013","scope":"Optional certified partner; setup vs guidance service; plan-specific scope not confirmed; documented partial scope; no independent product test, current customer version or contract confirmation"}','外部認定partner経由の代行・指導という選択肢の確認で、ベンダー従業員による一律代行/個別開発/検収保証ではない。専門勤務ルールの設定範囲・顧客側工数/準備・版/Expert契約への適用は未確認。days instead of weeksという広告を測定導入時間にしない。',NULL,NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B35-20261013','document_observation','B35-20261013-OBS0006','OF-US09','K03','known','{"summary_ja":"FAQはProサービスの地域をEMEAとNorth Americaとし、40 USD/hour・meetingは最大50分と表記する。設定依頼はaccount billing内の導線から予約し、請求はConnecteam経由で次回invoiceへ載ると説明する。"}','limited','unknown','documented','source_statement','{"record_category":"document_observation","research_batch":"B35-20261013","scope":"Optional certified partner; EMEA/North America in FAQ; USD public wording; hourly/session distinction unresolved; documented partial scope; no independent product test, current customer version or contract confirmation"}','公開LPの40 USD/50min sessionと時間単位が異なり、超過/作業継続分/単価算式・必要回数は未確定。日本からの契約可否・日本語/時差・地域例外・Expertへの含有は未確認。導線の存在を予約/認証権付与/費用発生と混同しない。課金画面へアクセスしていない。',NULL,NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B36-20261013','document_observation','B36-20261013-OBS0001','OF-US09','F04','not_found',NULL,'unknown','unknown','documented','source_statement','{"record_category":"document_observation","research_batch":"B36-20261013","scope":"General Connecteam homepage marketing; Operations Expert rule-input applicability unconfirmed; contextual observation only; criterion remains unconfirmed; not a non-support determination"}','宣伝文から任意制約の生成/保存、hard/soft、期間/単位/人数の解釈、例外/矛盾入力、日本語、プラン/preview/地域/顧客版を推測しない。リンク先の勤務製品ページとAI一覧/2025ガイドも対照したが、未記載を非対応にしない。製品AI/デモ実行なし。','公式トップはAIへ必要事項を伝えると勤務表を得られると案内するが、今回取得した本文では自然言語を実際の最適化ルールへ変換する仕様を確認できない。',NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B36-20261013','document_observation','B36-20261013-OBS0002','OF-US09','F04','not_found',NULL,'unknown','unknown','documented','source_statement','{"record_category":"document_observation","research_batch":"B36-20261013","scope":"Knowledge Base Agent; Communications Expert in help; response instructions distinct from Operations optimizer rules; contextual observation only; criterion remains unconfirmed; not a non-support determination"}','文書のrulesという語は回答方針の例。勤務条件のhard/softやソルバー入力ではない。Knowledge Base AgentはCommunications Hub Expert・最大20・SBP対象外という別Hub条件で、Operations Expert標準としない。現在の契約/モデル/日本語/実解釈は未確認。既存policy割当APIの一般事項は再登録しない。','Knowledge Base AgentのCustom Instructionsは知識庫を変えずに回答の焦点・避ける話題・口調を調整する設定と説明する。ここから勤務最適化ルールへの変換は確認できない。',NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B36-20261013','document_observation','B36-20261013-OBS0003','OF-US09','F05','not_found',NULL,'unknown','unknown','documented','source_statement','{"record_category":"document_observation","research_batch":"B36-20261013","scope":"Knowledge Base Agent settings review only; optimizer parse/approval scope unconfirmed; contextual observation only; criterion remains unconfirmed; not a non-support determination"}','設定の保存前確認と自然言語を解釈した規則の事前確認を区別。確認中の副作用抑止、勤務表生成/公開の承認、誤解釈/取消/競合、承認者権限、実画面と版は未確認。非対応の断定ではない。Agent作成/編集操作なし。','Agent編集は知識庫・名称・Custom Instructions・FAQ例・利用者/グループを選び、summary pageを確認してSave Changesする手順。勤務ルールの構造化解釈を適用前に承認する画面とは確認できない。',NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B36-20261013','document_observation','B36-20261013-OBS0004','OF-US09','F05','not_found',NULL,'unknown','unknown','documented','source_statement','{"record_category":"document_observation","research_batch":"B36-20261013","scope":"Knowledge Base Agent response provenance and maintenance; not optimizer interpretation approval evidence; contextual observation only; criterion remains unconfirmed; not a non-support determination"}','出典参照は回答根拠の追跡で、実行する制約・単位・期間・hard/softの構造化表示や承認ではない。確認前の自動適用/公開抑止・取消/復元・プラン/版/権限実挙動は未確認。会話保存や知識庫Q&Aを最適化規則対応へ加点しない。','利用者のchatは回答後にview sourcesから参照知識庫へ進める。不満な回答はCustom Instructionsか知識庫を更新して改善する案内だが、勤務条件解釈のプレビュー/確定手順は確認できない。',NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B37-20261013','document_observation','B37-20261013-OBS0001','OF-US09','D01','known','{"summary_ja":"JobのQualified欄で利用者・Smart Groupまたは両方を選ぶ。Sub-jobの適格者は既定で親Jobと同じで、Use same settings as parent jobを外すと別の利用者/群へ変えられる。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B37-20261013","scope":"Job/Sub-job qualified users or smart groups; help 2026-08-03; exact customer plan/version unconfirmed; documented limited or contextual scope; no independent product/credential test or customer contract/runtime confirmation"}','適格者の管理指定で、医療資格マスターとの照合・期限/失効の自動更新・資格AND/OR・職種組合せの必要人数/違反検出ではない。Smart Groupの所属変更反映時点、親設定変更/既存勤務への影響、顧客版/Expert権利・実拒否は未確認。既存自動割当の一般適格性を再登録しない。',NULL,NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B37-20261013','document_observation','B37-20261013-OBS0002','OF-US09','D01','known','{"summary_ja":"Open Shiftは勤務のJobを指定してavailable spotsを設定し、未充足枠数を表示する。公開・応募はそのJobの適格者が対象で、通常は先着応募で本人の勤務表へ追加される。Open ShiftはOperations Basic以上、承認付きはAdvancedからと説明する。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B37-20261013","scope":"Operations Basic+ open shifts; Advanced+ approval; qualifying Job required; help 2025-03-18; documented limited or contextual scope; no independent product/credential test or customer contract/runtime confirmation"}','1つのJobに対する募集枠と適格者範囲の部分確認。枠数は臨床配置基準・資格別最低人数や同一勤務の資格構成比ではない。資格失効/兼務二重計上・未充足違反の独立検算、実応募/Expert個別契約/上限/顧客版は未確認。既存一般Open Shift承認やC05応募制限は反復しない。',NULL,NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B37-20261013','document_observation','B37-20261013-OBS0003','OF-US09','B06','known','{"summary_ja":"Resource/Jobの作成時に、適格者と割り当てるTime Clock・Job Schedulerを選べる。同じJobを編集すると、そのJobを利用する他のTime Clock・Schedulerにも影響すると説明する。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B37-20261013","scope":"Resources Tab accounts; shared Job assignments across clocks/schedulers; plan/runtime unconfirmed; documented limited or contextual scope; no independent product/credential test or customer contract/runtime confirmation"}','共有するのはJob設定オブジェクト。施設/職種名をResourceとして表すことと、共有職員を複数表同時に最適化することは別。編集反映の原子性・既存割当再計算・アクセス範囲/顧客版/プラン・実境界は未試験。医療施設間移動/合算人数を推測しない。',NULL,NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B37-20261013','document_observation','B37-20261013-OBS0004','OF-US09','B06','known','{"summary_ja":"Time ClockまたはJob Schedulerが複数あるaccountでは、全Clock/SchedulerのJobを一元管理するJobs Tabを表示する。各1個だけのaccountでは独立Jobs Tabを表示せず、各機能内から管理する。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B37-20261013","scope":"Multiple-clock or multiple-scheduler accounts; centralized Job catalog only; help 2026-08-03; documented limited or contextual scope; no independent product/credential test or customer contract/runtime confirmation"}','一元管理はJob/適格者の設定場所で、一括勤務計画や同時ソルバー実行ではない。表をまたぐ職員需要の統合・同時更新・全施設最適性/不足充足は未確認。UI条件とライセンスの最大表数を混同せず、既存12スケジュールの根拠は追加しない。',NULL,NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B37-20261013','document_observation','B37-20261013-OBS0005','OF-US09','B06','known','{"summary_ja":"他表データを含める設定は勤務表ごとに有効化し、他表の草案勤務を含めるかも選択する。Cross-schedule events表示はView by Usersでのみ現れ、View by Jobには現れない。Time Off表示にはSchedulerとTime Clockの同期条件がある。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B37-20261013","scope":"Operations Expert+ Cross Schedule Issues; per-schedule toggle and Users view; help 2026-07-27; documented limited or contextual scope; no independent product/credential test or customer contract/runtime confirmation"}','他表情報の可視化条件を確認しただけで、一括最適化の実行範囲ではない。表示OFF/草案除外と内部自動割当の考慮を同一視しない。複数表の休息/最大時間/移動・同時編集・time-off種類/同期遅延は未試験。Cross Schedule IssuesはOperations Expertから、顧客の現行版/契約は未確認。',NULL,NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B37-20261013','document_observation','B37-20261013-OBS0006','OF-US09','B06','not_found',NULL,'unknown','unknown','documented','source_statement','{"record_category":"document_observation","research_batch":"B37-20261013","scope":"Operations Expert+ cross-schedule manual workflow; simultaneous optimization unconfirmed; documented limited or contextual scope; no independent product/credential test or customer contract/runtime confirmation"}','手動配置の通知は自動割当のhard条件/他表再配分の試験ではない。相互の未割当勤務をまとめて解くAPI/UI、全表共通目標/優先度、同時実行/更新競合、独立検算は未確認。既存の重複警告という一般事実を水増しせず、今回追加は明示的手動overrideと一括実行の留保。非対応とは断定しない。','Cross Schedule Issuesは他表の勤務/不可等を通知するが、通知にかかわらず管理者が配置しても阻止しないと明記する。この本文から共有職員を複数表で同時最適化する実行・結果は確認できない。',NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B38-20261013','document_observation','B38-20261013-OBS0001','OF-US09','N05','known','{"summary_ja":"KB Agent FAQは回答処理に必要な最小限の関連データをAzure OpenAI/Gemini/OpenAIへ送信し、処理後のLLM基盤で保持せず、モデル学習/改善にも利用しないと説明する。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B38-20261013","scope":"Communications KB Agent FAQ; provider-side processing claims only; public vendor statement only; no independent data-flow/permission test or executed customer contract confirmation"}','対象はCommunications Expert以上のKB Agent（20まで、SBP対象外）。送信フィールド一覧/自動匿名化/実プロンプト・provider別ルート/例外・ログ/Connecteam側履歴保持・顧客契約適用は未確認。Operations Expertの全AI/自動割当へ拡張しない。委託先一覧のAnthropicとの差は別記録へ保存。',NULL,NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B38-20261013','document_observation','B38-20261013-OBS0002','OF-US09','N05','known','{"summary_ja":"KB Agentは対象Agentの三点メニューからDeactivateでInactiveにし、Activateで再有効化すると説明する。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B38-20261013","scope":"Individual Communications KB Agent lifecycle; global opt-out untested; public vendor statement only; no independent data-flow/permission test or executed customer contract confirmation"}','個別KB Agentの状態操作であり、全AI/全外部送信の一括停止、既存データ削除/保持終了、Account Ownerの権限試験やスケジュールAI停止ではない。管理画面/送信停止の実観測/顧客版/復帰時挙動は未確認。',NULL,NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B38-20261013','document_observation','B38-20261013-OBS0003','OF-US09','N05','known','{"summary_ja":"AI特約のContent Rightsは、ConnecteamによるUser ContentでのAI Features横断学習/改善を禁じ、AI委託先のモデル学習/改善を積極的に許可しない一方、User Content/Outputをサービス提供・改善・保守等へ用い得ると記載する。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B38-20261013","scope":"Public Special AI Terms 2026-09-15; training wording and permitted service use distinguished; public vendor statement only; no independent data-flow/permission test or executed customer contract confirmation"}','公開2026-09-15版の文言で、独立した学習停止保証・全AIのzero retention・改善用途の保存期間を確定しない。FAQのLLM基盤保持とConnecteam内保持は別。対象顧客の締結版/付属契約、匿名化、具体送信項目/委託先別実装/第三者保証は未確認。',NULL,NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B38-20261013','document_observation','B38-20261013-OBS0004','OF-US09','N05','known','{"summary_ja":"利用規約1.7はAI機能がopt-inまたは既定有効になり、既定有効の場合Account Ownerがユーザー設定からopt outできると記載し、AI特約も適用すると説明する。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B38-20261013","scope":"Public Terms 2026-09-15; Account Owner opt out claim; feature-specific behavior untested; public vendor statement only; no independent data-flow/permission test or executed customer contract confirmation"}','設定名/入口/各Hub・機能への反映範囲・権限差/送信停止実測は未確認。AI特約のAgentic機能の既定有効/Administrator権限内実行と、KB個別Deactivateを同一UI/同一機能としない。顧客のOperations Expert提供権利や利用停止によるデータ削除を推測しない。',NULL,NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B38-20261013','document_observation','B38-20261013-OBS0005','OF-US09','N05','known','{"summary_ja":"公式委託先一覧はAzure OpenAIのSweden Central、生成AI用途のGoogle（米国）、AI機能用途のOpenAI（米国）に加え、AI Agent用途のAnthropic（米国）を載せる。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B38-20261013","scope":"Public subprocessor list; listed locations only; mismatch with KB FAQ preserved; public vendor statement only; no independent data-flow/permission test or executed customer contract confirmation"}','KB FAQのAzure OpenAI/Gemini/OpenAI列挙にはAnthropicがなく、資料の対象/版/機能差は未解消。Google会社一覧を全機能のGemini実行と断定せず、顧客ごとのprovider選択/region固定/越境・データ項目/学習・保持条件や第三者保証は未確認。一覧だけで全AI経路/契約を確定しない。',NULL,NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "observations"("batch_id","record_category","observation_id","offering_id","criterion_id","value_state","value_json","support_status","delivery_mode","verification_stage","assertion_kind","applicability_json","limitations","unknown_reason","valid_from","valid_to","recorded_on","reviewed_by","supersedes_observation_id") VALUES('B38-20261013','document_observation','B38-20261013-OBS0006','OF-US09','N05','known','{"summary_ja":"Privacy Noticeは顧客のUser Content等をprocessor/DPAの範囲に分け、processorデータは顧客指示の期間保持すると説明する。サポート等の通信記録による自社AI代表の改善は別のcontroller用途として記載する。"}','limited','native','documented','source_statement','{"record_category":"document_observation","research_batch":"B38-20261013","scope":"Privacy controller/processor roles 2026-09-15; customer retention and support AI distinct; public vendor statement only; no independent data-flow/permission test or executed customer contract confirmation"}','2026-09-15公開版。自社問い合わせAIの改善用途を顧客KB学習と同一視しない。顧客指示保持はLLM基盤zero retentionとは異なる。KB会話/ログ/埋込/バックアップ等の具体期間・AI送信項目/匿名化、契約版/削除検証/第三者保証は未確認でN05完了にしない。',NULL,NULL,NULL,'2026-10-13','Aqsh調査支援 / 公開一次資料レビュー',NULL);
INSERT INTO "source_archives"("revision_id","relative_path","sha256","media_type","page_count") VALUES('B23-20261012-REV003','assets/sources/B23-20261012/shiftwizard-support-faq.pdf','a7ae587e25b6cb9a672d528c129358bff56e8673f9d33058e31cb737b52e57c5','application/pdf',1);
